"use client";

import * as React from "react";
import { CaretDownIcon, CheckIcon } from "@phosphor-icons/react";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export interface PersonaAgentOption {
  agentId: string;
  voiceAgentId?: string;
  name: string;
  avatarUrl?: string;
}

interface AgentPickerProps {
  agents: PersonaAgentOption[];
  value?: string;
  onChange: (agentId: string) => void;
  className?: string;
}

/**
 * Top-left chat header control for switching between Agents. Picking a new
 * Agent starts a fresh conversation with it — the previous chat stays in the
 * thread list (see PersonaChatView's switch handler).
 */
export function AgentPicker({ agents, value, onChange, className }: AgentPickerProps) {
  const current = agents.find((a) => a.agentId === value) ?? agents[0];
  if (!current) return null;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        className={cn(
          "flex min-w-0 items-center gap-2 rounded-md px-1.5 py-1 text-sm font-medium outline-none transition-colors hover:bg-accent focus-visible:bg-accent",
          className
        )}
        aria-label="Switch agent"
      >
        <AgentAvatar name={current.name} avatarUrl={current.avatarUrl} className="size-6 text-[10px]" />
        <span className="max-w-40 truncate">{current.name}</span>
        <CaretDownIcon className="size-3.5 shrink-0 text-muted-foreground" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" sideOffset={6} className="min-w-56">
        {agents.map((agent) => (
          <DropdownMenuItem
            key={agent.agentId}
            onClick={() => onChange(agent.agentId)}
            className={cn(agent.agentId === value && "bg-accent/60")}
          >
            <AgentAvatar name={agent.name} avatarUrl={agent.avatarUrl} className="size-6 text-[10px]" />
            <span className="min-w-0 flex-1 truncate">{agent.name}</span>
            {agent.agentId === value && <CheckIcon className="ml-1 size-4 shrink-0" />}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function AgentAvatar({
  name,
  avatarUrl,
  className,
}: {
  name: string;
  avatarUrl?: string;
  className?: string;
}) {
  return avatarUrl ? (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={avatarUrl} alt="" className={cn("shrink-0 rounded-full object-cover", className)} />
  ) : (
    <span
      className={cn(
        "flex shrink-0 items-center justify-center rounded-full bg-primary/10 font-semibold text-primary",
        className
      )}
    >
      {initialsOf(name)}
    </span>
  );
}

function initialsOf(name: string) {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? "")
    .join("");
}

"use client";

import * as React from "react";
import {
  CheckCircleIcon,
  WarningCircleIcon,
  RobotIcon,
  GlobeIcon,
  PlugsIcon,
  TagIcon,
  SparkleIcon,
  FileTextIcon,
  LinkIcon,
} from "@phosphor-icons/react";
import { Badge } from "@/components/ui/badge";
import { MessageMarkdown } from "./message-markdown";
import { toolCallStatus } from "./tool-status";
import type { PersonaToolCall } from "@personaai/react";

/**
 * Body content rendered *inside* ToolCallCard, above the raw Input/Result,
 * whenever the assistant runs `manage_agent` with action "create"/"update"
 * — no card chrome of its own,
 * matching how write_todos renders TodoChecklist inside the same card.
 * Presents the create/update as a real form summary (what the tool is doing
 * and, once it returns, a success/error banner with the saved agent id) as a
 * quick read *in addition to* the raw args/result ToolCallCard still shows
 * underneath, same as every other tool call.
 *
 * `summarizeUpsert` derives the header fields (title/subtitle) for ToolCallCard
 * and the body data from one parse, so the collapsed and expanded states agree.
 */

function parseJson(raw: string | undefined): Record<string, unknown> | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as unknown;
    return parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

const str = (v: unknown): string =>
  typeof v === "string" ? v : typeof v === "number" ? String(v) : "";

/** id-ify a possibly-object providerId ({_id} / {id}) the way agent-form does. */
function idOf(v: unknown): string {
  if (typeof v === "string") return v;
  if (v && typeof v === "object") {
    const o = v as { _id?: unknown; id?: unknown };
    return str(o._id) || str(o.id);
  }
  return "";
}

function skillLabel(s: unknown): string {
  if (typeof s === "string") return s;
  if (s && typeof s === "object") {
    const o = s as { name?: unknown; title?: unknown; id?: unknown; _id?: unknown };
    return str(o.name) || str(o.title) || str(o.id) || str(o._id);
  }
  return "";
}

/** Shorten an object id for display while keeping it greppable on hover. */
function shortId(id: string, len = 8): string {
  if (id.length <= len) return id;
  return `${id.slice(0, 4)}…${id.slice(-4)}`;
}

function humanize(name: string): string {
  if (!name) return name;
  return name.charAt(0).toUpperCase() + name.slice(1);
}

export interface AgentUpsertSummary {
  isError: boolean;
  isPending: boolean;
  succeeded: boolean;
  isUpdate: boolean;
  title: string;
  subtitle?: string;
  message: string;
  name: string;
  description: string;
  modelName: string;
  providerId: string;
  category: string;
  visibility: string;
  webSearch: boolean;
  showWebSearch: boolean;
  tags: string[];
  skills: string[];
  mcps: string[];
  rcpSources: string[];
  systemPrompt: string;
}

export function summarizeUpsert(toolCall: PersonaToolCall): AgentUpsertSummary {
  const args = parseJson(toolCall.args);
  const result = parseJson(toolCall.result);

  const status = toolCallStatus(toolCall);
  const isPending = status === "running";
  const resultStatus = str(result?.status);
  const isError = status === "error" || resultStatus === "error";
  const succeeded = !isPending && !isError && resultStatus === "success";

  // manage_agent's fields live under `args.data` (not flat on `args` the way
  // the old single-purpose `upsert_agent` had them), and create-vs-update is
  // the explicit `args.action` now, not "does it carry an id".
  const action = str(args?.action);
  const argsData = (args?.data as Record<string, unknown> | undefined) ?? null;
  const resultAgentId =
    idOf(result?.agentId) || idOf((result?.data as Record<string, unknown> | undefined)?.id);

  const isUpdate = action === "update" || (!action && /updated/i.test(str(result?.message)));
  const isCreate = !isUpdate;

  // Prefer the authoritative saved payload once the call completes; while it is
  // running we can only echo back what was asked for.
  const saved = (result?.data as Record<string, unknown> | undefined) ?? null;
  const view: Record<string, unknown> = succeeded && saved ? saved : (argsData ?? {});

  const name = str(view.name) || str(saved?.name);
  const description = str(view.description) || str(saved?.description);
  const modelName = str(view.modelName) || str(saved?.modelName);
  const providerId = idOf(view.providerId) || idOf(saved?.providerId);
  const category = str(view.category) || str(saved?.category);
  const visibility = str(view.visibility) || str(saved?.visibility);
  const webSearch =
    (view.webSearchEnabled as boolean) ?? (saved?.webSearchEnabled as boolean);
  const showWebSearch =
    (view as Record<string, unknown>).webSearchEnabled !== undefined ||
    (saved != null && (saved as Record<string, unknown>).webSearchEnabled !== undefined);
  const tags = Array.isArray(view.tags)
    ? (view.tags as unknown[]).map(skillLabel).filter(Boolean)
    : [];
  const skills = Array.isArray(view.skills)
    ? (view.skills as unknown[]).map(skillLabel).filter(Boolean)
    : [];
  const mcps = Array.isArray(view.mcps)
    ? (view.mcps as unknown[]).map(skillLabel).filter(Boolean)
    : [];
  const rcpSources = Array.isArray(view.rcpSources)
    ? (view.rcpSources as unknown[]).map(skillLabel).filter(Boolean)
    : [];
  const systemPrompt = str(view.systemPrompt) || str(saved?.systemPrompt);

  const message = str(result?.message);

  const title = isError
    ? "Agent not saved"
    : isPending
      // Once the args have streamed in a name, show it directly (e.g. "Paper
      // Craft Pro") rather than the generic "Creating agent" — the human
      // reviewing this HITL card wants to know *which* agent, not just that
      // one is being written. Falls back to the generic phrasing only while
      // the name itself hasn't arrived yet.
      ? name || (isUpdate ? "Updating agent" : "Creating agent")
      : succeeded
        ? isUpdate
          ? "Agent updated"
          : "Agent created"
        : isCreate
          ? "Creating agent"
          : "Updating agent";

  const subtitle = isError
    ? message || "The agent tool reported an error."
    : isPending
      // Same idea for the subtitle: the agent's own description reads as
      // useful context for approve/reject; "Applying configuration…" doesn't.
      ? description || (name ? `Applying configuration for ${name}…` : "Applying configuration…")
      : succeeded
        ? `${name || "Agent"} · ${resultAgentId ? shortId(resultAgentId) : "saved"}`
        : name || undefined;

  return {
    isError,
    isPending,
    succeeded,
    isUpdate,
    title,
    subtitle,
    message,
    name,
    description,
    modelName,
    providerId,
    category,
    visibility,
    webSearch,
    showWebSearch,
    tags,
    skills,
    mcps,
    rcpSources,
    systemPrompt,
  };
}

// One inline "chip": icon + text, used for the model/web-search/provider meta
// strip — reads at a glance instead of a label/value form grid.
function MetaChip({ icon, children, title }: { icon: React.ReactNode; children: React.ReactNode; title?: string }) {
  return (
    <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground" title={title}>
      {icon}
      {children}
    </span>
  );
}

function AgentUpsertBody({ summary }: { summary: AgentUpsertSummary }) {
  const {
    isError,
    succeeded,
    isUpdate,
    message,
    name,
    description,
    modelName,
    providerId,
    category,
    visibility,
    webSearch,
    showWebSearch,
    tags,
    skills,
    mcps,
    rcpSources,
    systemPrompt,
  } = summary;

  return (
    <>
      {/* No separate pending banner here — the header (spinner icon, name,
          "…") already says this is in progress; a second "Writing agent
          configuration…" line under it was the same information twice. */}
      {isError ? (
        <div className="flex items-start gap-2 rounded-none border border-destructive/30 bg-destructive/10 px-3 py-2 text-xs text-destructive">
          <WarningCircleIcon className="mt-0.5 size-3.5 shrink-0" />
          <span>{message || "Failed to save the agent configuration."}</span>
        </div>
      ) : succeeded ? (
        <div className="flex items-center gap-2 rounded-none border border-emerald-500/20 bg-emerald-500/15 px-3 py-2 text-xs text-emerald-700 dark:text-emerald-400">
          <CheckCircleIcon className="size-3.5 shrink-0 text-emerald-500" />
          <span>{message || `Agent ${isUpdate ? "updated" : "created"}.`}</span>
        </div>
      ) : null}

      {name ? (
        <div className="flex flex-col gap-1.5">
          <div className="flex flex-wrap items-center gap-1.5">
            <span className="text-sm font-semibold text-foreground">{name}</span>
            {visibility ? <Badge variant="outline">{humanize(visibility)}</Badge> : null}
            {category ? <Badge variant="secondary">{humanize(category)}</Badge> : null}
          </div>
          {description ? (
            <p className="text-xs leading-relaxed text-muted-foreground">{description}</p>
          ) : null}

          {/* Model / web search / provider as a scannable icon+text strip
              instead of a label/value form grid — this is metadata to skim,
              not a form to read line by line. */}
          {(modelName || showWebSearch || providerId) && (
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1 pt-0.5">
              {modelName ? <MetaChip icon={<RobotIcon className="size-3.5" />}>{modelName}</MetaChip> : null}
              {showWebSearch ? (
                <MetaChip icon={<GlobeIcon className="size-3.5" />}>
                  Web search {webSearch ? "on" : "off"}
                </MetaChip>
              ) : null}
              {providerId ? (
                <MetaChip icon={<PlugsIcon className="size-3.5" />} title={providerId}>
                  {shortId(providerId, 20)}
                </MetaChip>
              ) : null}
            </div>
          )}

          {(tags.length > 0 || skills.length > 0 || mcps.length > 0 || rcpSources.length > 0) && (
            <div className="flex flex-col gap-1 pt-0.5">
              {tags.length > 0 ? (
                <div className="flex flex-wrap items-center gap-1.5">
                  <TagIcon className="size-3.5 shrink-0 text-muted-foreground" />
                  {tags.map((t) => (
                    <Badge key={t} variant="secondary">
                      {t}
                    </Badge>
                  ))}
                </div>
              ) : null}
              {skills.length > 0 ? (
                <div className="flex flex-wrap items-center gap-1.5">
                  <SparkleIcon className="size-3.5 shrink-0 text-muted-foreground" />
                  {skills.map((s) => (
                    <Badge key={s} variant="outline">
                      {s}
                    </Badge>
                  ))}
                </div>
              ) : null}
              {mcps.length > 0 ? (
                <div className="flex flex-wrap items-center gap-1.5">
                  <PlugsIcon className="size-3.5 shrink-0 text-muted-foreground" />
                  {mcps.map((m) => (
                    <Badge key={m} variant="outline">
                      {m}
                    </Badge>
                  ))}
                </div>
              ) : null}
              {rcpSources.length > 0 ? (
                <div className="flex flex-wrap items-center gap-1.5">
                  <LinkIcon className="size-3.5 shrink-0 text-muted-foreground" />
                  {rcpSources.map((r) => (
                    <Badge key={r} variant="outline">
                      {r}
                    </Badge>
                  ))}
                </div>
              ) : null}
            </div>
          )}
        </div>
      ) : null}

      {systemPrompt ? (
        <div className="flex flex-col gap-1">
          <div className="flex items-center gap-1.5 text-xs font-semibold text-muted-foreground">
            <FileTextIcon className="size-3.5" />
            Instructions
          </div>
          <div className="max-h-40 overflow-y-auto rounded-none border border-border bg-muted/50 px-3 py-2">
            <MessageMarkdown muted content={systemPrompt} />
          </div>
        </div>
      ) : null}
    </>
  );
}

export { AgentUpsertBody };

"use client";

import * as React from "react";
import {
  ArrowUpIcon,
  SquareIcon,
  PhoneXIcon,
  PaperclipIcon,
  XIcon,
  UploadSimpleIcon,
  FileIcon,
} from "@phosphor-icons/react";
import { Spinner } from "@/components/ui/spinner";
import type { PersonaAttachment } from "@personaai/react";
import { InputGroup, InputGroupTextarea, InputGroupAddon, InputGroupButton } from "@/components/ui/input-group";

function formatFileSize(bytes: number): string {
  if (!bytes || bytes <= 0) return "0 B";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

// Same "start voice mode" glyph NotebookChat.js's ComposerForm uses (a
// waveform, not a generic microphone) — inlined to match it exactly rather
// than substituting a similar-but-different icon from phosphor's set.
// VoiceTab's "Start voice call" button renders this; the composer itself no
// longer shows a voice-mode toggle (nothing in the Playground wires it, so
// it was a dead button), so VoiceModeIcon lives here only as a shared glyph.
function VoiceModeIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      {...props}
    >
      <path d="M2 10v3" />
      <path d="M6 6v11" />
      <path d="M10 3v18" />
      <path d="M14 8v8" />
      <path d="M18 5v14" />
      <path d="M22 10v3" />
    </svg>
  );
}

/**
 * Auto-resizing composer. The trailing action row is ALWAYS present, so the
 * composer keeps one steady height whether it is idle, streaming text, or
 * mid-voice-call — dropping the row when a surface has no voice button used
 * to shrink the idle composer into a short stub, so it is never conditionally
 * unmounted. Which action the row shows is computed by the caller:
 *
 *   streaming   → stop generating
 *   voice live  → stop the call, or send the typed text into the call
 *   default     → send message (dimmed until there is text to send)
 *
 * The idle send slot doubles as the voice-mode toggle when `onStartVoice` is
 * passed: with no text typed there is nothing to send, so that same slot
 * shows the waveform glyph instead of a permanently-dimmed arrow — one
 * control, not a separate always-on button bolted above the composer.
 *

 * The empty-state send is dimmed with `pointer-events-none` + reduced opacity
 * rather than a native `disabled` attribute — InputGroup greys out its WHOLE
 * contents via `has-disabled` when any child is disabled, which would wash
 * out the text field too.
 *
 * Deliberately no custom rounding/background overrides here — `InputGroup`/
 * `InputGroupButton` already carry this app's actual look (sharp
 * `rounded-none` everywhere, `Button`'s own variant colors), stacking a
 * borrowed rounded-pill/rounded-full treatment on top of them is exactly
 * what looked inconsistent and over-padded before.
 */
function ChatComposer({
  value,
  onChange,
  onSend,
  onStop,
  onStartVoice,
  onStopVoice,
  onSendToVoice,
  onSendImageToVoice,
  isStreaming = false,
  isVoiceActive = false,
  disabled = false,
  placeholder,
  attachments,
  onAddAttachments,
  onRemoveAttachment,
  isUploadingAttachments = false,
  attachmentError,
}: {
  value: string;
  onChange: (value: string) => void;
  onSend: () => void;
  onStop?: () => void;
  /** Shown in the send slot instead of a dimmed arrow whenever the field is empty and idle. */
  onStartVoice?: () => void;
  onStopVoice?: () => void;
  onSendToVoice?: (text: string) => void;
  /** During a live call, picked/pasted/dropped images go straight into the call (no upload step). */
  onSendImageToVoice?: (file: File) => void;
  isStreaming?: boolean;
  isVoiceActive?: boolean;
  disabled?: boolean;
  placeholder?: string;
  attachments?: PersonaAttachment[];
  onAddAttachments?: (files: FileList | File[] | null) => void;
  onRemoveAttachment?: (id: string) => void;
  isUploadingAttachments?: boolean;
  attachmentError?: string | null;
}) {
  const fileInputRef = React.useRef<HTMLInputElement | null>(null);
  const [isDragging, setIsDragging] = React.useState(false);
  const dragCounter = React.useRef(0);
  const trimmed = value.trim();
  const hasReadyAttachments =
    (attachments?.filter((a) => a.status === "ready").length ?? 0) > 0;
  const canSend =
    (trimmed || hasReadyAttachments) && !isUploadingAttachments && !isStreaming;

  const submit = () => {
    if (!canSend) return;
    if (isVoiceActive) {
      if (trimmed) onSendToVoice?.(trimmed);
    } else if (!isStreaming) {
      onSend();
    }
  };

  const voiceImages = isVoiceActive && !!onSendImageToVoice;
  const addImages = (files: File[]) => {
    if (files.length === 0) return;
    if (voiceImages) {
      files.forEach((file) => onSendImageToVoice?.(file));
    } else if (!isVoiceActive) {
      onAddAttachments?.(files);
    }
  };

  const handlePaste = (e: React.ClipboardEvent) => {
    if (e.clipboardData.files && e.clipboardData.files.length > 0) {
      const files = Array.from(e.clipboardData.files);
      if (files.length > 0) {
        e.preventDefault();
        addImages(files);
      }
    }
  };

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    dragCounter.current += 1;
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      setIsDragging(true);
    }
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    dragCounter.current -= 1;
    if (dragCounter.current <= 0) {
      dragCounter.current = 0;
      setIsDragging(false);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    dragCounter.current = 0;
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files);
      addImages(files);
    }
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submit();
      }}
      onPaste={handlePaste}
      onDragEnter={handleDragEnter}
      onDragLeave={handleDragLeave}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
      className="relative"
    >
      <input
        ref={fileInputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp,image/gif"
        multiple
        className="hidden"
        onChange={(e) => {
          if (e.target.files && e.target.files.length > 0) {
            addImages(Array.from(e.target.files));
            e.target.value = "";
          }
        }}
      />

      {/* Drag & Drop Visual Overlay */}
      {isDragging && (
        <div className="absolute inset-0 z-20 flex flex-col items-center justify-center rounded-lg border-2 border-dashed border-primary bg-background/95 backdrop-blur-xs animate-in fade-in-0 zoom-in-95 duration-100 pointer-events-none">
          <UploadSimpleIcon className="size-6 text-primary animate-bounce mb-1" />
          <span className="text-xs font-semibold text-primary">Drop images or files to attach</span>
          <span className="text-[10px] text-muted-foreground mt-0.5">
            PNG, JPG, WEBP, GIF (up to 5 MB each)
          </span>
        </div>
      )}

      <InputGroup>
        {!isVoiceActive && attachments && attachments.length > 0 && (
          <InputGroupAddon align="block-start" className="flex-wrap gap-2 pb-2 pt-1">
            {attachments.map((att) => (
              <div
                key={att.id}
                className="group relative flex items-center gap-2 rounded-md border border-border/70 bg-card/60 hover:bg-card/90 p-1.5 pr-2 transition-all shadow-2xs max-w-[200px]"
              >
                {/* Thumbnail / Icon */}
                <div className="relative size-7 shrink-0 rounded overflow-hidden border border-border/40 bg-muted flex items-center justify-center">
                  {att.previewUrl ? (
                    <img
                      src={att.previewUrl}
                      alt={att.name}
                      className="size-full object-cover"
                    />
                  ) : (
                    <FileIcon className="size-3.5 text-muted-foreground" />
                  )}
                  {att.status === "uploading" && (
                    <div className="absolute inset-0 bg-background/70 flex items-center justify-center">
                      <Spinner className="size-3 text-primary" />
                    </div>
                  )}
                </div>

                {/* Name & Size badge */}
                <div className="flex flex-col min-w-0 pr-1 leading-tight">
                  <span
                    className="truncate text-[11px] font-medium text-foreground max-w-[110px]"
                    title={att.name}
                  >
                    {att.name}
                  </span>
                  <span className="text-[10px] text-muted-foreground font-mono">
                    {formatFileSize(att.size)}
                  </span>
                </div>

                {att.status === "error" && (
                  <span className="text-[9px] font-semibold text-destructive shrink-0">
                    Failed
                  </span>
                )}

                {/* Remove button */}
                {onRemoveAttachment && (
                  <button
                    type="button"
                    onClick={() => onRemoveAttachment(att.id)}
                    className="size-4 shrink-0 rounded-full flex items-center justify-center text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors ml-auto"
                    aria-label={`Remove ${att.name}`}
                  >
                    <XIcon className="size-3" />
                  </button>
                )}
              </div>
            ))}
          </InputGroupAddon>
        )}

        <InputGroupTextarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              submit();
            }
          }}
          placeholder={placeholder ?? (isVoiceActive ? "Type to voice…" : "Ask anything…")}
          rows={1}
          disabled={disabled}
          className="max-h-40"
        />

        <InputGroupAddon align="block-end" className="justify-between">
          <div className="flex items-center gap-1.5">
            {(!isVoiceActive || voiceImages) && (
              <InputGroupButton
                type="button"
                variant="ghost"
                size="icon-sm"
                aria-label={voiceImages ? "Show an image in the call" : "Attach images"}
                title={voiceImages ? "Show an image in the call" : undefined}
                disabled={
                  disabled ||
                  (!voiceImages && (isStreaming || (attachments?.length ?? 0) >= 4))
                }
                onClick={() => fileInputRef.current?.click()}
              >
                <PaperclipIcon className="size-4" />
              </InputGroupButton>
            )}
            {attachmentError && (
              <span className="text-[11px] text-destructive truncate max-w-[200px]" title={attachmentError}>
                {attachmentError}
              </span>
            )}
          </div>

          <div className="flex items-center gap-1.5">
            {isStreaming ? (
              <InputGroupButton
                type="button"
                variant="secondary"
                size="icon-sm"
                aria-label="Stop generating"
                onClick={onStop}
              >
                <SquareIcon weight="fill" />
              </InputGroupButton>
            ) : isVoiceActive ? (
              <div className="flex items-center gap-1.5">
                {trimmed ? (
                  <InputGroupButton type="submit" variant="default" size="icon-sm" aria-label="Send to voice">
                    <ArrowUpIcon />
                  </InputGroupButton>
                ) : null}
                <InputGroupButton
                  type="button"
                  variant="destructive"
                  size="icon-sm"
                  aria-label="Stop voice"
                  onClick={onStopVoice}
                >
                  <PhoneXIcon />
                </InputGroupButton>
              </div>
            ) : !trimmed && !hasReadyAttachments && onStartVoice ? (
              <InputGroupButton
                type="button"
                variant="outline"
                size="icon-sm"
                aria-label="Start voice call"
                onClick={onStartVoice}
              >
                <VoiceModeIcon className="size-4" />
              </InputGroupButton>
            ) : (
              <InputGroupButton
                type="submit"
                variant="default"
                size="icon-sm"
                aria-label="Send message"
                // Dim but not natively disabled (see note above): pointer-events
                // off so an empty click no-ops and focuses the field instead.
                className={canSend ? undefined : "pointer-events-none opacity-40"}
              >
                {isUploadingAttachments ? <Spinner className="size-3.5" /> : <ArrowUpIcon />}
              </InputGroupButton>
            )}
          </div>
        </InputGroupAddon>
      </InputGroup>
    </form>
  );
}

