function parseJsonObject(value?: string): Record<string, unknown> {
  if (!value || typeof value !== "string") return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

// Raw tool names like `beu_mcp__browse_content` are too long for the
// widget's slim header (and the `ui://` URI is noise for end users), so
// show only the last segment, humanized.
function formatAppName(toolName?: string) {
  if (!toolName) return "MCP App";
  const lastSegment = toolName.split("__").pop() || toolName;
  const words = lastSegment.replace(/[_-]+/g, " ").trim();
  return words ? words.charAt(0).toUpperCase() + words.slice(1) : "MCP App";
}

function buildToolResultPayload(tool?: { result?: string }) {
  let structuredContent: unknown = undefined;
  if (tool?.result) {
    try {
      structuredContent = JSON.parse(tool.result);
    } catch {
      // plain text fallback
    }
  }

  const content = [
    {
      type: "text" as const,
      text: typeof tool?.result === "string" ? tool.result : "",
    },
  ];

  return structuredContent !== undefined
    ? { content, structuredContent }
    : { content };
}

export interface McpAppResource {
  text?: string;
  mimeType?: string;
}

export interface McpAppRendererProps {
  /** Inline HTML content to load directly into the widget iframe. */
  initialHtml?: string;
  /** Resource URI to fetch HTML content from (e.g. "ui://dashboard" or an HTTP/API URL). */
  resourceUri?: string;
  /** Custom handler to resolve an MCP resource URI into HTML text. */
  onReadResource?: (uri: string) => Promise<McpAppResource>;
  /** Custom handler to invoke an MCP tool triggered from within the widget. */
  onCallTool?: (name: string, args?: Record<string, unknown>) => Promise<unknown>;
  /** MCP connector backing this widget. Its resource reads and tool calls
   *  go through the Persona runtime (`useMcp`). */
  mcpId?: string;
  toolName?: string;
  tool?: {
    args?: string;
    result?: string;
    status: "running" | "done" | "error";
  };
  className?: string;
  height?: number;
  /** Initial height of the inline widget; the header button always opens it
   *  full screen. */
  expanded?: boolean;
  onSendMessage?: (text: string) => void;
}

/**
 * McpAppRenderer — renders an interactive MCP App widget inside a sandboxed
 * iframe, connected via AppBridge JSON-RPC-over-postMessage.
 */
export function McpAppRenderer({
  mcpId,
  resourceUri,
  initialHtml,
  onReadResource,
  onCallTool,
  toolName,
  tool,
  className,
  height = 450,
  expanded = true,
  onSendMessage,
}: McpAppRendererProps) {
  // Reads the widget's `ui://` HTML and calls tools through the runtime
  // adapter (`/mcps/:id/resource`, `/mcps/:id/call-tool`).
  const { readResource, callTool } = useMcp();
  const wrapperRef = React.useRef<HTMLDialogElement | null>(null);
  const iframeRef = React.useRef<HTMLIFrameElement | null>(null);
  const bridgeRef = React.useRef<AppBridge | null>(null);
  const resultSentRef = React.useRef(false);
  const onSendMessageRef = React.useRef(onSendMessage);
  onSendMessageRef.current = onSendMessage;
  const [html, setHtml] = React.useState<string | null>(initialHtml || null);
  const [loading, setLoading] = React.useState(!initialHtml);
  const [error, setError] = React.useState<string | null>(null);
  const [fullscreen, setFullscreen] = React.useState(false);
  const [contentHeight, setContentHeight] = React.useState<number | null>(null);
  const setAppSplit = React.useContext(McpAppSplitContext)?.setSplit;

  // TEMP DEBUG — widget lifecycle trace.
  React.useEffect(() => {
    console.info("[mcp-app] mounted", {
      mcpId,
      resourceUri,
      hasInitialHtml: !!initialHtml,
      toolName,
      toolStatus: tool?.status,
    });
  }, [mcpId, resourceUri, initialHtml, toolName, tool?.status]);

  // 1. Resolve widget HTML content
  React.useEffect(() => {
    if (initialHtml) {
      setHtml(initialHtml);
      setLoading(false);
      setError(null);
      return;
    }

    if (!resourceUri) {
      setError("No HTML content or resource URI provided for MCP App");
      setLoading(false);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);
    setHtml(null);
    setContentHeight(null);

    const resolveHtml = async (): Promise<string> => {
      // 1. If custom onReadResource handler is provided by caller
      if (onReadResource) {
        const res = await onReadResource(resourceUri);
        if (!res?.text) throw new Error("Empty resource response from MCP server");
        return res.text;
      }

      // 2. If resourceUri is an HTTP URL, fetch it directly
      if (resourceUri.startsWith("http://") || resourceUri.startsWith("https://") || resourceUri.startsWith("/")) {
        console.debug("[mcp-app] resolving resource via URL", resourceUri);
        const res = await fetch(resourceUri);
        if (!res.ok) throw new Error(`Failed to fetch MCP resource (${res.status})`);
        return res.text();
      }

      // 3. `ui://` (and any other MCP resource URI) resolves through the
      // Persona runtime adapter, using the connector id the backend attached
      // to this tool call via the `mcp_app` stream event.
      if (mcpId) {
        console.info("[mcp-app] reading resource via runtime", { mcpId, resourceUri });
        const result = await readResource(resourceUri, mcpId);
        const data = result?.data ?? result;
        console.info("[mcp-app] resource response", {
          mimeType: data?.mimeType ?? null,
          textLength: typeof data?.text === "string" ? data.text.length : 0,
        });
        if (!data?.text) throw new Error("Empty resource response from MCP server");
        return data.text as string;
      }

      console.error("[mcp-app] no connector id on this tool call", { resourceUri });
      throw new Error(
        `Cannot resolve MCP resource "${resourceUri}". Provide initialHtml, onReadResource, a connector id, or a valid URL.`
      );
    };

    resolveHtml()
      .then((text) => {
        if (cancelled) return;
        console.info("[mcp-app] widget HTML resolved", { length: text.length });
        setHtml(text);
        setLoading(false);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        console.error("[mcp-app] failed to resolve widget", err);
        const e = err as { response?: { data?: { message?: string } }; message?: string };
        const msg = e?.response?.data?.message || e.message || "Failed to load MCP App";
        setError(msg);
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [initialHtml, resourceUri, onReadResource, mcpId, readResource]);

  // 2. Wire up AppBridge and load HTML into sandboxed iframe
  React.useEffect(() => {
    if (!html || !iframeRef.current) return;

    const iframe = iframeRef.current;
    resultSentRef.current = false;

    const bridge = new AppBridge(
      null,
      { name: "persona-platform", version: "1.0.0" },
      {
        message: { text: {} },
        openLinks: {},
        serverTools: {},
        serverResources: {},
        updateModelContext: { text: {} },
      },
      {
        hostContext: {
          theme:
            typeof document !== "undefined" && document.documentElement.classList.contains("dark")
              ? "dark"
              : "light",
          platform: "web",
          displayMode: "inline",
          availableDisplayModes: ["inline"],
        },
      }
    );

    bridge.oncalltool = async (params: { name: string; arguments?: Record<string, unknown> }) => {
      console.info("[mcp-app] widget called a tool", { name: params.name, mcpId });
      if (onCallTool) {
        return onCallTool(params.name, params.arguments);
      }
      if (mcpId) {
        const json = await callTool(params.name, params.arguments, mcpId);
        console.info("[mcp-app] tool call response", { name: params.name });
        return json?.data ?? json;
      }
      console.warn("[mcp-app] tool call dropped — no connector id", { name: params.name });
      return null;
    };

    bridge.onreadresource = async (params: { uri: string }) => {
      console.info("[mcp-app] widget read a resource", { uri: params.uri, mcpId });
      if (onReadResource) {
        const res = await onReadResource(params.uri);
        return {
          contents: [
            {
              uri: params.uri,
              mimeType: res.mimeType || "text/html",
              text: res.text || "",
            },
          ],
        };
      }
      if (mcpId) {
        const result = await readResource(params.uri, mcpId);
        const data = result?.data ?? result;
        return {
          contents: [
            {
              uri: params.uri,
              mimeType: data?.mimeType || "text/html",
              text: data?.text || "",
            },
          ],
        };
      }
      return { contents: [] };
    };

    bridge.onopenlink = async ({ url }: { url: string }) => {
      if (typeof window !== "undefined") {
        window.open(url, "_blank", "noopener,noreferrer");
      }
      return {};
    };

    bridge.onmessage = async ({ content }) => {
      console.info("[mcp-app] widget sent a message", { content });
      if (Array.isArray(content)) {
        const text = content
          .filter(
            (b): b is { type: "text"; text: string } =>
              b?.type === "text" && typeof (b as { text?: unknown }).text === "string"
          )
          .map((b) => b.text)
          .join("\n")
          .trim();
        if (text) {
          onSendMessageRef.current?.(text);
        }
      }
      return {};
    };
    bridge.onupdatemodelcontext = async () => ({});

    bridge.oninitialized = () => {
      console.info("[mcp-app] bridge initialized — sending tool input", {
        toolStatus: tool?.status,
        hasArgs: !!tool?.args,
      });
      bridge.sendToolInput({ arguments: parseJsonObject(tool?.args) });
      if (tool?.status === "done" && typeof tool?.result === "string") {
        console.info("[mcp-app] sending tool result at init");
        resultSentRef.current = true;
        bridge.sendToolResult(buildToolResultPayload(tool));
      }
    };

    const handleSizeChange = ({ height: newHeight }: { height?: number }) => {
      if (newHeight !== undefined && newHeight !== null) {
        setContentHeight(newHeight);
      }
    };
    bridge.addEventListener("sizechange", handleSizeChange);

    let cancelled = false;
    if (iframe.contentWindow) {
      const transport = new PostMessageTransport(iframe.contentWindow, iframe.contentWindow);
      console.info("[mcp-app] connecting bridge");
      bridge
        .connect(transport)
        .then(() => {
          if (cancelled) return;
          console.info("[mcp-app] bridge connected — loading widget HTML into iframe", {
            htmlLength: html.length,
          });
          iframe.srcdoc = html;
        })
        .catch((err) => {
          if (cancelled) return;
          console.error("[mcp-app] bridge connect failed", err);
          setError(err?.message || "Failed to connect to MCP App bridge");
        });
    } else {
      console.warn("[mcp-app] iframe contentWindow unavailable — skipping bridge connect");
    }

    bridgeRef.current = bridge;

    return () => {
      cancelled = true;
      bridgeRef.current = null;
      bridge.removeEventListener("sizechange", handleSizeChange);
      bridge.close?.();
    };
  }, [html, mcpId, readResource, callTool]);

  // 3. Forward tool result once it arrives
  React.useEffect(() => {
    const bridge = bridgeRef.current;
    if (!bridge || resultSentRef.current) return;
    if (tool?.status !== "done" || typeof tool?.result !== "string") return;
    console.info("[mcp-app] forwarding late tool result to widget");
    resultSentRef.current = true;
    bridge.sendToolResult(buildToolResultPayload(tool));
  }, [tool?.status, tool?.result]);

  // Full screen is the same <dialog> promoted to the top layer with
  // `showModal()`. The iframe must stay put — the AppBridge dies if it
  // remounts — and the top layer escapes the FAB panel's transform/clipping
  // that would otherwise trap a `position: fixed` overlay.
  const enterFullscreen = React.useCallback(() => {
    const el = wrapperRef.current;
    if (!el) return;
    try {
      if (!el.open) el.showModal();
      console.info("[mcp-app] entered full screen", { toolName });
      // Before paint, so the chat column has already made room when the
      // dialog appears.
      setAppSplit?.(true);
      setFullscreen(true);
    } catch (err) {
      console.error("[mcp-app] failed to open full screen", err);
    }
  }, [toolName, setAppSplit]);

  const exitFullscreen = React.useCallback(() => {
    const el = wrapperRef.current;
    if (el?.open) el.close();
    setAppSplit?.(false);
    setFullscreen(false);
  }, [setAppSplit]);

  // The dialog's `close` event also fires when Escape dismisses it, so this
  // is the single place state syncs back.
  const handleDialogClose = React.useCallback(() => {
    console.info("[mcp-app] exited full screen", { toolName });
    setAppSplit?.(false);
    setFullscreen(false);
  }, [toolName, setAppSplit]);

  // A modal dialog has no default backdrop dismissal; clicks on the
  // `::backdrop` retarget to the <dialog> element itself.
  const handleDialogClick = React.useCallback(
    (event: React.MouseEvent<HTMLDialogElement>) => {
      if (!fullscreen || event.target !== event.currentTarget) return;
      exitFullscreen();
    },
    [fullscreen, exitFullscreen]
  );

  // Escape reaches the window listener in `persona-chat-fab` that closes the
  // panel; while full screen, it should only exit the dialog. Capture phase
  // on window runs before that bubble-phase listener.
  React.useEffect(() => {
    if (!fullscreen) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") event.stopPropagation();
    };
    window.addEventListener("keydown", handleKeyDown, true);
    return () => window.removeEventListener("keydown", handleKeyDown, true);
  }, [fullscreen]);

  // Ask the chat to give the app the right side of the viewport, so the
  // conversation is squeezed to the left rather than covered. Cleanup runs
  // when the widget closes and when it unmounts while still open.
  React.useEffect(() => {
    if (!fullscreen) return;
    setAppSplit?.(true);
    return () => setAppSplit?.(false);
  }, [fullscreen, setAppSplit]);

  if (error) {
    return (
      <div
        className={cn(
          "rounded-none border border-destructive/30 bg-destructive/10 p-4 text-destructive",
          className
        )}
      >
        <div className="flex items-start gap-2.5">
          <WarningCircleIcon className="size-5 shrink-0 mt-0.5" />
          <div className="min-w-0">
            <p className="text-xs font-semibold">Failed to load MCP App</p>
            <p className="mt-1 text-xs opacity-80">{error}</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <dialog
      ref={wrapperRef}
      onClose={handleDialogClose}
      onClick={handleDialogClick}
      aria-label={`MCP App: ${toolName || resourceUri || "widget"}`}
      className={cn(
        "group m-0 max-w-full overflow-hidden border border-border p-0 text-foreground",
        fullscreen
          ? "fixed inset-y-0 right-0 left-auto flex h-dvh w-full max-h-none max-w-none flex-col bg-background shadow-2xl backdrop:bg-transparent md:w-3/5"
          : "relative block w-full bg-card",
        className
      )}
    >
      {/* Header bar — intentionally minimal: a short label and the
          expand/close controls. The raw tool name and `ui://` URI are
          unbreakable strings that used to widen the chat column. */}
      <div
        className={cn(
          "flex min-w-0 shrink-0 items-center justify-between gap-2 overflow-hidden border-b border-border bg-muted/40 text-xs text-muted-foreground",
          fullscreen ? "px-4 py-2.5" : "px-3 py-1.5"
        )}
      >
        <div className="flex min-w-0 flex-1 items-center gap-1.5">
          <AppWindowIcon className="size-3.5 shrink-0 text-primary" />
          <span
            className="min-w-0 truncate text-[11px] font-semibold text-foreground"
            title={toolName || resourceUri}
          >
            {formatAppName(toolName || resourceUri)}
          </span>
        </div>

        <div className="flex shrink-0 items-center gap-1">
          {fullscreen ? (
            <>
              <button
                type="button"
                onClick={exitFullscreen}
                className="flex size-6 cursor-pointer items-center justify-center text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                title="Exit full screen"
                aria-label="Exit full screen"
              >
                <ArrowsInIcon className="size-3.5" />
              </button>
              <button
                type="button"
                onClick={exitFullscreen}
                className="flex size-6 cursor-pointer items-center justify-center text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                title="Close app"
                aria-label="Close app"
              >
                <XIcon className="size-3.5" />
              </button>
            </>
          ) : (
            <button
              type="button"
              onClick={enterFullscreen}
              className="flex size-6 cursor-pointer items-center justify-center text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              title="Open full screen"
              aria-label="Open full screen"
            >
              <ArrowsOutIcon className="size-3.5" />
            </button>
          )}
        </div>
      </div>

      {/* Loading state */}
      {loading && (
        <div
          className={cn(
            "flex flex-col items-center justify-center gap-2 p-8 text-muted-foreground",
            fullscreen && "min-h-0 flex-1"
          )}
          style={fullscreen ? undefined : { height: `${height}px` }}
        >
          <Spinner className="size-5 text-primary" />
          <p className="text-xs">Loading MCP App…</p>
        </div>
      )}

      {/* Sandboxed iframe */}
      <iframe
        ref={iframeRef}
        sandbox="allow-scripts allow-forms"
        onLoad={() => console.info("[mcp-app] iframe loaded", { toolName, resourceUri })}
        className={cn(
          "block w-full max-w-full border-0 bg-white dark:bg-zinc-950",
          fullscreen ? "min-h-0 flex-1" : "transition-[height] duration-200 ease-in-out",
          loading && "hidden"
        )}
        style={
          !loading && !fullscreen
            ? {
                height:
                  contentHeight !== null
                    ? `${contentHeight}px`
                    : expanded
                      ? "calc(80vh - 8rem)"
                      : `${height}px`,
                maxHeight: expanded ? "calc(90vh - 6rem)" : `${height}px`,
              }
            : undefined
        }
        title={`MCP App: ${formatAppName(toolName || resourceUri)}`}
      />
    </dialog>
  );
}

"use client";

import * as React from "react";
import {
  ArrowSquareOutIcon,
  CheckCircleIcon,
  KeyIcon,
  WarningCircleIcon,
  XIcon,
} from "@phosphor-icons/react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import type { PersonaMcpConnection } from "@personaai/react";
import type { McpConnectionNotice as McpConnectionNoticeState } from "./use-persona-chat-widget";

const STATUS_HINTS: Partial<Record<NonNullable<PersonaMcpConnection["status"]>, string>> = {
  needs_auth: "Access was revoked or expired",
  expired: "Your sign-in expired",
  not_connected: "Hasn't been connected yet",
};

/**
 * User-mode MCP connectors this end user hasn't connected. Their tools are
 * dropped from the Agent's toolset server-side, so without this banner the
 * capability just silently isn't there. Connect/Reconnect hands off to
 * `onConnect`, which redirects to the provider's consent page; the backend's
 * OAuth callback returns here, which remounts the page and refetches
 * connection state.
 */
export function McpConnectBanner({
  connections,
  blockedMcpIds,
  onConnect,
  className,
}: {
  connections: PersonaMcpConnection[];
  /** Ids the last run actually dropped tools for (the `mcp_auth_required` event). */
  blockedMcpIds?: ReadonlySet<string>;
  onConnect: (connection: PersonaMcpConnection) => void;
  className?: string;
}) {
  if (connections.length === 0) return null;
  const blocked = connections.some((c) => blockedMcpIds?.has(c.mcpId));

  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "overflow-hidden rounded-none border border-border bg-card text-xs",
        className
      )}
    >
      <div className="flex items-start gap-2.5 border-b border-border/70 bg-muted/30 px-3 py-2.5">
        <span className="mt-px flex size-6 shrink-0 items-center justify-center border border-border bg-background text-muted-foreground">
          <KeyIcon className="size-3.5" />
        </span>
        <div className="flex min-w-0 flex-col gap-0.5">
          <span className="font-semibold text-foreground">
            {blocked ? "Some tools were skipped in this reply" : "Connect accounts to unlock more tools"}
          </span>
          <span className="text-muted-foreground">
            {blocked
              ? "This assistant can't use these tools until you connect your account."
              : "This assistant has tools it can only use after you connect your account."}
          </span>
        </div>
      </div>
      <ul className="divide-y divide-border/70">
        {connections.map((c) => {
          const hint = STATUS_HINTS[c.status ?? "not_connected"];
          const needsReconnect = c.status === "needs_auth" || c.status === "expired";
          return (
            <li key={c.mcpId} className="flex items-center justify-between gap-3 px-3 py-2">
              <span className="flex min-w-0 flex-col">
                <span className="truncate font-medium text-foreground">{c.name}</span>
                {hint && <span className="truncate text-[11px] text-muted-foreground">{hint}</span>}
              </span>
              <Button
                type="button"
                size="sm"
                variant={needsReconnect ? "default" : "outline"}
                disabled={!c.authorizeUrl}
                onClick={() => onConnect(c)}
              >
                {needsReconnect ? "Reconnect" : "Connect"}
                <ArrowSquareOutIcon className="size-3" />
              </Button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/**
 * The confirmation for an OAuth round trip: the return used to be completely
 * silent — same page, no change — so users couldn't tell a successful connect
 * from a cancelled one. Success clears itself after a few seconds; failures
 * stay until dismissed because they need acting on.
 */
export function McpConnectionNotice({
  notice,
  onDismiss,
  className,
}: {
  notice: McpConnectionNoticeState;
  onDismiss: () => void;
  className?: string;
}) {
  const success = notice.kind === "success";

  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "flex items-start gap-2.5 border px-3 py-2.5 text-xs",
        success
          ? "border-emerald-500/30 bg-emerald-500/10"
          : "border-destructive/30 bg-destructive/10",
        className
      )}
    >
      {success ? (
        <CheckCircleIcon weight="fill" className="mt-px size-4 shrink-0 text-emerald-500" />
      ) : (
        <WarningCircleIcon weight="fill" className="mt-px size-4 shrink-0 text-destructive" />
      )}
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span
          className={cn(
            "font-medium",
            success ? "text-emerald-700 dark:text-emerald-300" : "text-destructive"
          )}
        >
          {success ? `Connected to ${notice.name}` : `Couldn't connect to ${notice.name}`}
        </span>
        <span
          className={cn(
            success
              ? "text-emerald-700/80 dark:text-emerald-300/80"
              : "text-destructive/80"
          )}
        >
          {success
            ? "Its tools are ready to use in your next message."
            : notice.message ?? "The connection wasn't completed. You can try again."}
        </span>
      </div>
      <button
        type="button"
        aria-label="Dismiss"
        onClick={onDismiss}
        className="-mr-1 -mt-1 flex size-6 shrink-0 items-center justify-center text-muted-foreground hover:text-foreground"
      >
        <XIcon className="size-3.5" />
      </button>
    </div>
  );
}

"use client";

import * as React from "react";
import { CheckCircleIcon, KeyIcon, PlugsIcon } from "@phosphor-icons/react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Spinner } from "@/components/ui/spinner";
import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "@/lib/utils";
import type { PersonaMcpConnection } from "@personaai/react";

type McpStatus = NonNullable<PersonaMcpConnection["status"]>;

const STATUS_LABELS: Record<McpStatus, string> = {
  connected: "Connected",
  expired: "Expired",
  needs_auth: "Needs auth",
  not_connected: "Not connected",
};

const STATUS_DOTS: Record<McpStatus, string> = {
  connected: "bg-emerald-500",
  expired: "bg-destructive",
  needs_auth: "bg-destructive",
  not_connected: "bg-muted-foreground/50",
};

/** Backends predating `status` only send the boolean — derive the finer state. */
function statusOf(connection: PersonaMcpConnection): McpStatus {
  return connection.status ?? (connection.connected ? "connected" : "not_connected");
}

/** Short, locale-aware "expires" hint for connectors with a token lifetime. */
function formatExpiry(expiresAt: string | null | undefined) {
  if (!expiresAt) return null;
  const date = new Date(expiresAt);
  if (Number.isNaN(date.getTime())) return null;
  return `Expires ${date.toLocaleDateString(undefined, { month: "short", day: "numeric" })}`;
}

function ConnectorTile({ name }: { name: string }) {
  const initial = name.trim().charAt(0).toUpperCase() || "?";
  return (
    <span
      aria-hidden="true"
      className="flex size-8 shrink-0 items-center justify-center border border-border bg-muted/40 text-xs font-semibold text-muted-foreground"
    >
      {initial}
    </span>
  );
}

export interface McpConnectionsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Every user-mode MCP attached to the Agent (`useMcpConnections().connections`). */
  connections: PersonaMcpConnection[];
  /** Loads the consent flow and redirects to the provider. */
  onConnect: (connection: PersonaMcpConnection) => void;
  /** Revokes this end user's stored grant (DELETE …/oauth/user/connection). */
  onRevoke: (mcpId: string) => Promise<void>;
  /** The connector just confirmed by the OAuth callback — highlighted once. */
  justConnectedMcpId?: string | null;
  isLoading?: boolean;
}

/**
 * The managing view the connect banner can't be: one row per user-mode MCP,
 * showing whether this end user's account is connected and letting them
 * either start the consent flow (same-tab redirect to `authorizeUrl`) or
 * revoke the stored grant. Revoking only drops this user's token — the
 * connector itself stays attached to the Agent.
 */
export function McpConnectionsDialog({
  open,
  onOpenChange,
  connections,
  onConnect,
  onRevoke,
  justConnectedMcpId,
  isLoading,
}: McpConnectionsDialogProps) {
  const isMobile = useIsMobile();
  const [revokingId, setRevokingId] = React.useState<string | null>(null);
  const [error, setError] = React.useState<string | null>(null);

  const handleRevoke = React.useCallback(
    async (mcpId: string) => {
      setRevokingId(mcpId);
      setError(null);
      try {
        await onRevoke(mcpId);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to revoke access.");
      } finally {
        setRevokingId(null);
      }
    },
    [onRevoke]
  );

  const connectedCount = connections.filter((c) => statusOf(c) === "connected").length;

  const body = (
    <div className="flex min-h-0 flex-1 flex-col overflow-y-auto">
      {isLoading && connections.length === 0 ? (
        <ul className="divide-y divide-border" aria-busy="true">
          {[0, 1].map((i) => (
            <li key={i} className="flex items-center gap-3 px-4 py-3">
              <span className="size-8 shrink-0 animate-pulse border border-border bg-muted/60" />
              <div className="flex flex-1 flex-col gap-1.5">
                <span className="h-3 w-32 animate-pulse bg-muted" />
                <span className="h-2.5 w-48 animate-pulse bg-muted/70" />
              </div>
            </li>
          ))}
        </ul>
      ) : connections.length === 0 ? (
        <div className="flex flex-col items-center gap-2 px-4 py-8 text-center">
          <PlugsIcon className="size-6 text-muted-foreground" />
          <p className="text-xs text-muted-foreground">
            No connectors are attached to this assistant.
          </p>
        </div>
      ) : (
        <ul className="divide-y divide-border">
          {connections.map((connection) => {
            const status = statusOf(connection);
            const isConnected = status === "connected";
            const needsReconnect = status === "needs_auth" || status === "expired";
            const revoking = revokingId === connection.mcpId;
            const justConnected = justConnectedMcpId === connection.mcpId;
            const expiry = isConnected ? formatExpiry(connection.expiresAt) : null;
            return (
              <li
                key={connection.mcpId}
                className={cn(
                  "flex items-start justify-between gap-3 px-4 py-3 transition-colors",
                  justConnected && "bg-emerald-500/5"
                )}
              >
                <div className="flex min-w-0 items-start gap-3">
                  <ConnectorTile name={connection.name} />
                  <div className="flex min-w-0 flex-col gap-1">
                    <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                      <span className="truncate text-sm font-medium">{connection.name}</span>
                      <span className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
                        <span
                          aria-hidden="true"
                          className={cn("size-1.5 rounded-full", STATUS_DOTS[status])}
                        />
                        {STATUS_LABELS[status]}
                        {justConnected && (
                          <span className="flex items-center gap-1 text-emerald-600 dark:text-emerald-400">
                            <CheckCircleIcon weight="fill" className="size-3" />
                            just now
                          </span>
                        )}
                      </span>
                    </div>
                    {connection.description && (
                      <span className="line-clamp-2 text-xs text-muted-foreground">
                        {connection.description}
                      </span>
                    )}
                    {connection.lastError && needsReconnect && (
                      <span className="text-xs text-destructive">{connection.lastError}</span>
                    )}
                    {expiry && (
                      <span className="text-[11px] text-muted-foreground">{expiry}</span>
                    )}
                  </div>
                </div>
                <div className="flex shrink-0 items-center gap-1">
                  {isConnected ? (
                    <Button
                      type="button"
                      size="sm"
                      variant="ghost"
                      className="text-muted-foreground hover:text-destructive"
                      disabled={revoking || revokingId !== null}
                      onClick={() => void handleRevoke(connection.mcpId)}
                    >
                      {revoking && <Spinner className="size-3" />}
                      Disconnect
                    </Button>
                  ) : (
                    <Button
                      type="button"
                      size="sm"
                      variant={needsReconnect ? "default" : "outline"}
                      disabled={!connection.authorizeUrl}
                      onClick={() => onConnect(connection)}
                    >
                      {needsReconnect ? "Reconnect" : "Connect"}
                    </Button>
                  )}
                </div>
              </li>
            );
          })}
        </ul>
      )}
      {error && <p className="px-4 pb-3 text-xs text-destructive">{error}</p>}
    </div>
  );

  const description = `${connectedCount} of ${connections.length} connected. Revoking removes the stored access token; the connector stays attached to the assistant.`;

  if (isMobile) {
    return (
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent
          side="bottom"
          className="flex w-full flex-col gap-0 overflow-hidden rounded-t-lg p-0 outline-none data-[side=bottom]:h-[70vh] data-[side=bottom]:max-h-[70vh]"
        >
          <SheetHeader className="flex shrink-0 flex-row items-center justify-between border-b border-border bg-muted/20 px-4 py-3">
            <div className="flex flex-col gap-0.5">
              <SheetTitle className="flex items-center gap-2 text-sm font-semibold tracking-tight">
                <span className="flex size-6 items-center justify-center rounded-none bg-primary text-primary-foreground">
                  <KeyIcon className="size-3.5" />
                </span>
                Connected accounts
              </SheetTitle>
              <SheetDescription className="text-xs text-muted-foreground">
                {description}
              </SheetDescription>
            </div>
          </SheetHeader>
          {body}
        </SheetContent>
      </Sheet>
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[80vh] flex-col gap-0 overflow-hidden p-0 outline-none sm:max-w-lg">
        <DialogHeader className="flex shrink-0 flex-row items-center justify-between border-b border-border bg-muted/20 px-5 py-3">
          <div className="flex min-w-0 flex-col gap-0.5">
            <DialogTitle className="flex items-center gap-2 text-sm font-semibold tracking-tight">
              <span className="flex size-6 items-center justify-center rounded-none bg-primary text-primary-foreground">
                <KeyIcon className="size-3.5" />
              </span>
              Connected accounts
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              {description}
            </DialogDescription>
          </div>
        </DialogHeader>
        {body}
      </DialogContent>
    </Dialog>
