"use client";

import * as React from "react";
import { FolderOpenIcon, RobotIcon, SparkleIcon } from "@phosphor-icons/react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { useIsMobile } from "@/hooks/use-mobile";
import { useMemory, type PersonaMemoryFile } from "@personaai/react";
import { FileExplorerEditor, type ExplorerItem } from "@/components/file-explorer/file-explorer-editor";

function stripLeadingSlash(path: string): string {
  return path.replace(/^\/+/, "");
}

function toBackendPath(path: string): string {
  return `/${stripLeadingSlash(path)}`;
}

type MemoryScope = NonNullable<PersonaMemoryFile["scope"]>;

/** `memories/agent/...` and `memories/user/...` map to real scope+path; `workspace/...` doesn't need unprefixing (its own item). */
function resolveMemoriesPath(path: string): { scope: Extract<MemoryScope, "agent" | "user">; path: string } {
  const clean = stripLeadingSlash(path);
  if (clean.startsWith("agent/")) return { scope: "agent", path: toBackendPath(clean.slice("agent/".length)) };
  return { scope: "user", path: toBackendPath(clean.startsWith("user/") ? clean.slice("user/".length) : clean) };
}

export interface MemoryWorkspaceDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /**
   * The Agent whose memory/workspace to show. Workspace files are scoped by
   * Agent + Subject (shared across every conversation with that Agent);
   * agent-scoped memory is scoped the same way; user-scoped memory applies
   * across every Agent this Subject talks to.
   */
  agentId: string | undefined;
  /** Jump straight to this workspace file once the dialog is showing — e.g. a present_file "Open" click. Leading slash optional. */
  initialOpenPath?: string | null;
}

type MemoryWorkspaceItem = ExplorerItem;

/**
 * File-explorer-style dialog over both a Subject's memory (`/memories/user/`
 * shared across every Agent, `/memories/agent/` scoped to this one Agent)
 * and this Agent's `/workspace/` files — the SAME two persistent stores an
 * Agent's own `write_file`/`read_file` tool calls actually read and write
 * (NOT a Thread's LangGraph checkpoint state, a different, much narrower
 * thing). Same VS Code-style tree/tabs/editor shell as the platform's own
 * Skill/Agent bundle editor (`FileExplorerEditor`) and the same two-item
 * shape as the platform's own `MemoryWorkspaceDialog` — backed directly by
 * `@personaai/react`'s `useMemory` instead of a parallel type/adapter layer.
 * No "+ new item" affordance (`onCreateItem` left unset): the two items are
 * fixed, new files are created via each item's own "+ Add file" link.
 */
export function MemoryWorkspaceDialog({
  open,
  onOpenChange,
  agentId,
  initialOpenPath,
}: MemoryWorkspaceDialogProps) {
  const isMobile = useIsMobile();
  const { memory, isLoading, writeFile, deleteFile } = useMemory(open);
  const [openRequest, setOpenRequest] = React.useState<{ itemId: string; path: string | null } | null>(
    null
  );

  const items = React.useMemo<MemoryWorkspaceItem[] | null>(() => {
    if (
      isLoading &&
      memory.userFiles.length === 0 &&
      memory.agentMemories.length === 0 &&
      memory.agentWorkspaces.length === 0
    ) {
      return null;
    }
    if (!agentId) return [];

    const agentGroup = memory.agentMemories.find((g) => g.agentId === agentId);
    const workspaceGroup = memory.agentWorkspaces.find((g) => g.agentId === agentId);

    const memoriesFiles = [
      ...(agentGroup?.files ?? []).map((f) => ({
        path: `agent/${stripLeadingSlash(f.path)}`,
        content: f.content,
      })),
      ...memory.userFiles.map((f) => ({ path: `user/${stripLeadingSlash(f.path)}`, content: f.content })),
    ].sort((a, b) => a.path.localeCompare(b.path));

    const workspaceFiles = (workspaceGroup?.files ?? [])
      .map((f) => ({ path: stripLeadingSlash(f.path), content: f.content }))
      .sort((a, b) => a.path.localeCompare(b.path));

    return [
      { id: "memories", name: "memories", files: memoriesFiles },
      { id: "workspace", name: "workspace", files: workspaceFiles },
    ];
  }, [memory, isLoading, agentId]);

  // A present_file "Open" click always jumps to that workspace file, every
  // time it changes — not just once per dialog open.
  React.useEffect(() => {
    if (open && initialOpenPath) {
      setOpenRequest({ itemId: "workspace", path: stripLeadingSlash(initialOpenPath) });
    }
  }, [open, initialOpenPath]);

  const handleSaveFile = React.useCallback(
    async (item: MemoryWorkspaceItem, path: string, content: string) => {
      if (item.id === "memories") {
        const { scope, path: backendPath } = resolveMemoriesPath(path);
        await writeFile({ path: backendPath, content, scope, agentId: scope === "agent" ? agentId : undefined });
      } else {
        await writeFile({ path: toBackendPath(path), content, scope: "workspace", agentId });
      }
    },
    [writeFile, agentId]
  );

  const handleAddFile = React.useCallback(
    async (item: MemoryWorkspaceItem, path: string) => {
      await handleSaveFile(item, path, "");
    },
    [handleSaveFile]
  );

  const handleDeleteFile = React.useCallback(
    async (item: MemoryWorkspaceItem, path: string) => {
      if (item.id === "memories") {
        const { scope, path: backendPath } = resolveMemoriesPath(path);
        await deleteFile({ path: backendPath, scope, agentId: scope === "agent" ? agentId : undefined });
      } else {
        await deleteFile({ path: toBackendPath(path), scope: "workspace", agentId });
      }
    },
    [deleteFile, agentId]
  );

  const handleDeleteItem = React.useCallback(
    async (item: MemoryWorkspaceItem) => {
      for (const f of item.files) {
        await handleDeleteFile(item, f.path).catch(() => {});
      }
    },
    [handleDeleteFile]
  );

  const explorer = (
    <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
      <FileExplorerEditor<MemoryWorkspaceItem>
        items={items}
        itemLabelPlural="directories"
        onSaveRoot={async () => {}}
        onSaveFile={handleSaveFile}
        onDeleteItem={handleDeleteItem}
        onAddFile={handleAddFile}
        onDeleteFile={handleDeleteFile}
        openRequest={openRequest}
        emptyStateTitle="No file open"
        emptyStateDescription="Select a file from the explorer tree, or use '+ Add file' to create one."
        addFilePlaceholder={(item) =>
          item?.id === "memories" ? "e.g. agent/notes.md or user/preferences.md" : "e.g. outputs/report.md"
        }
        renderTabExtras={(item, activePath) => {
          if (item.id === "workspace") {
            return (
              <Badge variant="outline" className="rounded-none bg-muted/50 px-1.5 py-0 font-mono text-[10px] uppercase tracking-wide">
                <span className="inline-flex items-center gap-1">
                  <FolderOpenIcon className="size-2.5 text-primary" />
                  Workspace
                </span>
              </Badge>
            );
          }
          const isShared = activePath?.startsWith("user/") ?? false;
          return (
            <Badge variant="outline" className="rounded-none bg-muted/50 px-1.5 py-0 font-mono text-[10px] uppercase tracking-wide">
              {isShared ? (
                <span className="inline-flex items-center gap-1">
                  <SparkleIcon className="size-2.5 text-primary" />
                  Shared
                </span>
              ) : (
                <span className="inline-flex items-center gap-1">
                  <RobotIcon className="size-2.5 text-primary" />
                  Agent
                </span>
              )}
            </Badge>
          );
        }}
      />
    </div>
  );

  if (isMobile) {
    return (
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent
          side="bottom"
          className="flex w-full flex-col gap-0 overflow-hidden rounded-t-lg p-0 outline-none data-[side=bottom]:h-[96vh] data-[side=bottom]:min-h-[96vh] data-[side=bottom]:max-h-[96vh]"
        >
          <SheetHeader className="flex shrink-0 flex-row items-center justify-between border-b border-border bg-muted/20 px-4 py-3">
            <div className="flex flex-col gap-0.5">
              <SheetTitle className="flex items-center gap-2 text-sm font-semibold tracking-tight">
                <span className="flex size-6 items-center justify-center rounded-none bg-primary text-primary-foreground">
                  <FolderOpenIcon className="size-3.5" />
                </span>
                Memory &amp; Workspace
              </SheetTitle>
              <SheetDescription className="text-xs text-muted-foreground">
                This agent&apos;s shared/agent memory and its /workspace/ files.
              </SheetDescription>
            </div>
          </SheetHeader>
          {explorer}
        </SheetContent>
      </Sheet>
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex h-[86vh] w-[95vw] flex-col gap-0 overflow-hidden p-0 outline-none sm:max-w-7xl">
        <DialogHeader className="flex shrink-0 flex-row items-center justify-between border-b border-border bg-muted/20 px-5 py-3">
          <div className="flex flex-col gap-0.5">
            <DialogTitle className="flex items-center gap-2 text-sm font-semibold tracking-tight">
              <span className="flex size-6 items-center justify-center rounded-none bg-primary text-primary-foreground">
                <FolderOpenIcon className="size-3.5" />
              </span>
              Memory &amp; Workspace
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              This agent&apos;s shared/agent memory and its /workspace/ files.
            </DialogDescription>
          </div>
        </DialogHeader>
        {explorer}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";
import { Skeleton } from "@/components/ui/skeleton";
import { SvgPreview } from "@/components/svg/svg-preview";
import { MessageMarkdown } from "./message-markdown";
import type { SearchResultItem } from "./tool-cards/search-citation-card";

/**
 * Splits assistant message content on ```svg fenced blocks and renders each
 * SVG block as an actual inline <svg> element (dangerouslySetInnerHTML of the
 * SVG markup inside a sandboxed wrapper). Prose segments between SVG blocks
 * are passed through MessageMarkdown as normal.
 *
 * Security: only the content inside the <svg>…</svg> tags is injected; the
 * outer wrapper is a plain <div> we control. Script tags and event-handler
 * attributes inside SVGs are stripped before rendering.
 */

// Matches a full ```svg … ``` fence (non-greedy, dotAll).
const SVG_FENCE_RE = /```svg\s*\n([\s\S]*?)```/g;
const FENCE_MARKER = "```";

interface Segment {
  type: "markdown" | "svg";
  content: string;
}

interface SplitResult {
  segments: Segment[];
  /** True while the text ends inside a ```svg fence that is still streaming. */
  pendingSvg: boolean;
}

/**
 * While a fence is streaming in, its closing ``` hasn't arrived yet. An odd
 * number of fence markers in the tail means the last one is unclosed; return
 * it so we can swap the raw code for a skeleton.
 */
function findUnclosedFence(tail: string): { index: number; info: string } | null {
  const markerCount = tail.split(FENCE_MARKER).length - 1;
  if (markerCount % 2 === 0) return null;

  const index = tail.lastIndexOf(FENCE_MARKER);
  const infoLine = tail
    .slice(index + FENCE_MARKER.length)
    .split("\n", 1)[0]
    .trim()
    .toLowerCase();
  return { index, info: infoLine.split(/[ \t]/, 1)[0] };
}

function splitSegments(text: string, detectPending: boolean): SplitResult {
  const segments: Segment[] = [];
  let lastIndex = 0;

  for (const match of text.matchAll(SVG_FENCE_RE)) {
    const fenceStart = match.index!;
    // Prose before this fence
    if (fenceStart > lastIndex) {
      const prose = text.slice(lastIndex, fenceStart).trim();
      if (prose) segments.push({ type: "markdown", content: prose });
    }
    segments.push({ type: "svg", content: match[1].trim() });
    lastIndex = fenceStart + match[0].length;
  }

  const tail = text.slice(lastIndex);
  const unclosed = detectPending ? findUnclosedFence(tail) : null;
  // "s" / "sv" / "svg" — still typing the info string out.
  const pendingIndex =
    unclosed && "svg".startsWith(unclosed.info) ? unclosed.index : null;

  if (pendingIndex !== null) {
    // Drop the fence content: it's half-written SVG source, not prose.
    const prose = tail.slice(0, pendingIndex).trim();
    if (prose) segments.push({ type: "markdown", content: prose });
  } else {
    const prose = tail.trim();
    if (prose) segments.push({ type: "markdown", content: prose });
  }

  const pendingSvg = pendingIndex !== null;

  if (segments.length === 0 && !pendingSvg) {
    segments.push({ type: "markdown", content: text });
  }

  return { segments, pendingSvg };
}

/**
 * Renders the SVG bare — no card, border, or caption — sized to the message
 * column. Normalization (viewBox present, fixed width/height removed) lives in
 * SvgPreview so chat and the file explorer size SVGs the same fluid way.
 */
function InlineSvg({ raw }: { raw: string }) {
  return (
    <SvgPreview
      source={raw}
      className="my-3 flex justify-center [&>svg]:max-h-[480px]"
    />
  );
}

/**
 * Placeholder for an SVG that's still streaming in: a big shimmering
 * rectangle roughly the size of the final drawing, instead of raw markup.
 */
function SvgSkeleton() {
  return (
    <div className="my-3 w-full" role="img" aria-label="Generating image">
      <Skeleton className="h-80 w-full" />
    </div>
  );
}

/**
 * Drop-in replacement for `<MessageMarkdown content={…} />` on assistant
 * messages. Detects ```svg fences, renders them as real SVGs, and passes
 * everything else to the normal Streamdown markdown renderer.
 */
function MessageContentWithSvg({
  content,
  className,
  streaming = false,
  sources,
}: {
  content: string;
  className?: string;
  /** While true, an unclosed ```svg fence renders as a skeleton, not code. */
  streaming?: boolean;
  /** Optional web search sources for interactive inline [1] citations */
  sources?: SearchResultItem[];
}) {
  const { segments, pendingSvg } = React.useMemo(
    () => splitSegments(content, streaming),
    [content, streaming]
  );

  // Fast path: no SVG blocks at all — avoid extra elements
  if (!pendingSvg && segments.length === 1 && segments[0].type === "markdown") {
    return <MessageMarkdown content={content} className={className} sources={sources} />;
  }

  return (
    <div className="flex flex-col gap-1">
      {segments.map((seg, i) =>
        seg.type === "svg" ? (
          // biome-ignore lint/suspicious/noArrayIndexKey: segments are positional
          <InlineSvg key={i} raw={seg.content} />
        ) : (
          // biome-ignore lint/suspicious/noArrayIndexKey: segments are positional
          <MessageMarkdown key={i} content={seg.content} className={className} sources={sources} />
        )
      )}
      {pendingSvg && <SvgSkeleton />}
    </div>
  );
}

export { MessageContentWithSvg };

import type { PersonaMessage, PersonaToolCall, PersonaSubagentActivityEntry } from "@personaai/react";

export interface GroupedMessage {
  message: PersonaMessage;
  /** `role:"reasoning"` messages that streamed immediately before this one — undefined except on an assistant message with reasoning ahead of it. */
  reasoningPhases?: PersonaMessage[];
}

/**
 * Groups the SDK's flat `messages` array (reasoning phases as their own
 * `role:"reasoning"` entries, in stream order — the wire protocol's shape)
 * into pairs the visual layer can render: each assistant message paired
 * with the reasoning phases that preceded it. `message` is always the real
 * `PersonaMessage`, untouched — `reasoningPhases` is a sibling, not a field
 * grafted onto a copy of it. System messages are dropped.
 */
export function groupReasoning(messages: PersonaMessage[]): GroupedMessage[] {
  const result: GroupedMessage[] = [];
  let pending: PersonaMessage[] = [];

  for (const msg of messages) {
    if (msg.role === "system") continue;

    if (msg.role === "reasoning") {
      pending.push(msg);
      continue;
    }

    result.push({
      message: msg,
      reasoningPhases: msg.role === "assistant" && pending.length ? pending : undefined,
    });
    pending = [];
  }

  return result;
}

/**
 * A subagent (`task` tool call)'s `subagentActivity` is a flat timeline of
 * text/tool_start/tool_result entries, not its own message array — flatten
 * it into one assistant `PersonaMessage` so `SubagentSheet` can replay it
 * through the same `ChatMessage` component as a top-level turn.
 */
export function flattenSubagentActivity(
  toolCallId: string,
  activity: PersonaSubagentActivityEntry[]
): PersonaMessage[] {
  let content = "";
  const toolCalls: PersonaToolCall[] = [];
  const byName = new Map<string, PersonaToolCall>();
  let seq = 0;

  for (const entry of activity) {
    if (entry.kind === "text") {
      content += entry.delta ?? "";
    } else if (entry.kind === "tool_start") {
      const call: PersonaToolCall = {
        toolCallId: `${toolCallId}-sub-${seq++}`,
        toolName: entry.toolName ?? "tool",
        args: entry.args,
      };
      toolCalls.push(call);
      if (entry.toolName) byName.set(entry.toolName, call);
    } else if (entry.kind === "tool_result") {
      const call = entry.toolName ? byName.get(entry.toolName) : undefined;
      if (call) call.result = entry.result;
    }
  }

  return [
    {
      id: `${toolCallId}-subagent`,
      role: "assistant",
      content,
      createdAt: new Date(),
      toolCalls,
    },
  ];
}

"use client";

import * as React from "react";
import { Streamdown } from "streamdown";
import remarkGfm from "remark-gfm";
import { code } from "@streamdown/code";
import { cn } from "@/lib/utils";
import {
  MarkdownLink,
  transformInlineCitations,
} from "./inline-citation";
import type { SearchResultItem } from "./tool-cards/search-citation-card";

/**
 * Every markdown render in the library goes through this one wrapper.
 * `Streamdown` is purpose-built for partial/incomplete markdown mid-stream
 * (unclosed code fences, half-written tables) — the exact problem the
 * NotebookChat.js reference solved by hand, switching between a raw
 * streaming renderer and a full block renderer once a message finished.
 * One renderer, used for both states, is simpler and doesn't need that split.
 */
function MessageMarkdown({
  className,
  content,
  muted = false,
  sources,
}: {
  className?: string;
  content: string;
  /** Render in muted tones (used for reasoning/thinking blocks). */
  muted?: boolean;
  /** Optional web search sources for rendering interactive [1], [2] citation pills with popovers */
  sources?: SearchResultItem[];
}) {
  const processedContent = React.useMemo(() => {
    if (!sources || !sources.length) return content;
    return transformInlineCitations(content, sources.length);
  }, [content, sources]);

  return (
    <Streamdown
      className={cn(
        // Exactly one root color: streamdown text (and fenced code that inherits
        // rather than self-coloring) reads either foreground or muted. Appending
        // both would leave the winner to CSS source order, so muted swaps rather
        // than stacks. Links/inline chips below stay colorful in either state.
        "max-w-none text-xs/relaxed [&>*:first-child]:mt-0 [&>*:last-child]:mb-0",
        muted ? "text-muted-foreground" : "text-foreground",
        "[&_a]:text-primary [&_a]:underline [&_a]:underline-offset-4",
        // Only inline code gets our chip styling — fenced code blocks are
        // fully owned by Streamdown's own code-block renderer (header bar +
        // token colors from the `code` plugin); adding another border/bg/
        // padding layer around its <pre>/<code> just nests boxes inside
        // boxes.
        "[&_code:not(pre_code)]:rounded-none [&_code:not(pre_code)]:bg-muted [&_code:not(pre_code)]:px-1 [&_code:not(pre_code)]:py-0.5 [&_code:not(pre_code)]:text-xs",
        "[&_h1]:mt-4 [&_h1]:mb-2 [&_h1]:text-sm [&_h1]:font-semibold",
        "[&_h2]:mt-4 [&_h2]:mb-2 [&_h2]:text-sm [&_h2]:font-semibold",
        "[&_h3]:mt-3 [&_h3]:mb-1.5 [&_h3]:text-xs [&_h3]:font-semibold",
        "[&_ol]:my-2 [&_ol]:list-decimal [&_ol]:pl-5 [&_ul]:my-2 [&_ul]:list-disc [&_ul]:pl-5",
        "[&_p]:my-2 [&_p:first-of-type]:mt-0! [&_p:first-child]:mt-0! [&_p:last-of-type]:mb-0! [&_p:last-child]:mb-0!",
        // Wrap fenced code instead of letting it scroll horizontally —
        // a long unbroken line otherwise forces the code block wider than
        // its flex ancestors are willing to shrink to, which overflows the
        // whole page sideways on narrow (mobile) viewports.
        "[&_[data-streamdown=code-block-body]]:overflow-x-visible!",
        "[&_[data-streamdown=code-block-body]_pre]:whitespace-pre-wrap! [&_[data-streamdown=code-block-body]_pre]:break-words!",
        "[&_[data-streamdown=code-block-body]_code]:whitespace-pre-wrap! [&_[data-streamdown=code-block-body]_code]:break-words!",
        className
      )}
      remarkPlugins={[remarkGfm]}
      plugins={{ code }}
      controls={{ table: false }}
      components={{
        a: ({ href, children, ...rest }) => (
          <MarkdownLink href={href} sources={sources} {...rest}>
            {children}
          </MarkdownLink>
        ),
        table: ({ children, className: tableClassName, ...rest }) => (
          <div className="my-3 w-full overflow-x-auto">
            <table
              className={cn("w-full text-left text-xs border-collapse", tableClassName)}
              {...rest}
            >
              {children}
            </table>
          </div>
        ),
        thead: ({ children, className: theadClassName, ...rest }) => (
          <thead
            className={cn("border-b border-border/80 font-semibold text-foreground", theadClassName)}
            {...rest}
          >
            {children}
          </thead>
        ),
        tbody: ({ children, className: tbodyClassName, ...rest }) => (
          <tbody
            className={cn("divide-y divide-border/40", tbodyClassName)}
            {...rest}
          >
            {children}
          </tbody>
        ),
        tr: ({ children, className: trClassName, ...rest }) => (
          <tr
            className={cn("transition-colors hover:bg-muted/20", trClassName)}
            {...rest}
          >
            {children}
          </tr>
        ),
        th: ({ children, className: thClassName, ...rest }) => (
          <th
            className={cn(
              "py-2.5 pr-4 pl-0 text-left font-semibold text-foreground/90 first:pl-0 last:pr-0 whitespace-nowrap",
              thClassName
            )}
            {...rest}
          >
            {children}
          </th>
        ),
        td: ({ children, className: tdClassName, ...rest }) => (
          <td
            className={cn(
              "py-2.5 pr-4 pl-0 text-foreground/80 first:pl-0 last:pr-0 align-top",
              tdClassName
            )}
            {...rest}
          >
            {children}
          </td>
        ),
      }}
    >
      {processedContent}
    </Streamdown>
  );
}

