"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { MessageMarkdown } from "./message-markdown";
import type { PersonaMessage } from "@personaai/react";

function formatElapsed(ms: number): string {
  const seconds = Math.max(0, Math.round(ms / 1000));
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes}m ${seconds % 60}s`;
}

/**
 * One reasoning/thinking block, adapted from the old dashboard's
 * ReasoningBubble (itself from JimLiu/claude-agent-kit, MIT): an italic
 * collapsible header that auto-opens while the block is streaming and
 * auto-collapses once the backend stamps a duration, unless the user toggles
 * it. The thought text renders muted below a hairline so the final answer
 * stays the visual focus.
 */
function ReasoningBlock({
  reasoning,
  className,
}: {
  reasoning: PersonaMessage;
  className?: string;
}) {
  const isStreaming = !!reasoning.isStreaming;

  // Derive open state from the live stream unless the user flips it manually;
  // manualOpen starts null so the first render follows isStreaming.
  const [manualOpen, setManualOpen] = React.useState<boolean | null>(null);
  const open = manualOpen ?? isStreaming;

  // Live "Thought · Ns" label while a block is still streaming. PersonaMessage
  // carries no started-at timestamp, so this clocks from first render instead
  // of the block's real open time — close enough for a live ticker, and
  // finished blocks just show "Thought" with no duration (the SDK doesn't
  // stamp one).
  const [mountedAt] = React.useState(() => Date.now());
  const [now, setNow] = React.useState(() => Date.now());
  React.useEffect(() => {
    if (!isStreaming) return;
    const id = window.setInterval(() => setNow(Date.now()), 500);
    return () => window.clearInterval(id);
  }, [isStreaming]);

  const liveElapsed = formatElapsed(Math.max(0, now - mountedAt));
  const doneElapsed: string | null = null;

  const hasContent = !!reasoning.content?.trim();
  const headerLabel = hasContent
    ? `Thoughts${doneElapsed ? ` for ${doneElapsed}` : ""}`
    : "Thinking";

  return (
    <div
      className={cn(
        "max-w-full text-muted-foreground select-text",
        !open && "-mb-0.5",
        className
      )}
    >
      <button
        type="button"
        onClick={() => setManualOpen(!open)}
        aria-expanded={open}
        className="group flex cursor-pointer items-center py-0.5 text-xs font-medium text-foreground/90 transition-colors hover:text-foreground select-none focus-visible:outline-none"
      >
        <span className="text-xs font-medium text-foreground/90 group-hover:text-foreground transition-colors">
          {isStreaming ? (
            <span className="inline-flex items-center gap-1">
              <span>Thinking</span>
              <span className="animate-pulse">…</span>
            </span>
          ) : (
            headerLabel
          )}
        </span>
      </button>

      {open ? (
        <div className="mt-1 text-[11px] text-muted-foreground/80 leading-relaxed">
          {hasContent ? (
            <MessageMarkdown
              muted
              content={reasoning.content}
              className="text-[11px] leading-relaxed [&_p]:my-1.5"
            />
          ) : (
            <span className="text-[11px] text-muted-foreground/70">
              {isStreaming ? `Started ${liveElapsed} ago` : "No reasoning captured."}
            </span>
          )}
        </div>
      ) : null}
    </div>
  );
}

export { ReasoningBlock };

"use client";

import * as React from "react";
import { TerminalIcon } from "@phosphor-icons/react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { useIsMobile } from "@/hooks/use-mobile";
import { Spinner } from "@/components/ui/spinner";
import type { PersonaSandboxCommand } from "@personaai/react";

// Matches ANSI/CSI escape codes (e.g. from `curl -v`), which render as
// literal garbage (␛[1m...) instead of formatting in a plain <div>.
const ANSI_ESCAPE_RE = /\x1b\[[0-9;]*[a-zA-Z]/g;
function stripAnsi(text: string): string {
  return text.replace(ANSI_ESCAPE_RE, "");
}

export interface SandboxTerminalDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** `useChat()`'s own `sandboxCommands` — already parsed `execute` tool calls, no adapter needed. */
  commands: PersonaSandboxCommand[];
}

/**
 * Read-only, live transcript of the agent's sandbox activity — a terminal-
 * styled view directly over `@personaai/react`'s `useChat()`'s own
 * `sandboxCommands` (derived from the same `execute` tool calls already
 * streaming into the chat). No polling, no fetch: a pure derived view, so
 * it stays in sync with the conversation for free.
 */
export function SandboxTerminalDialog({ open, onOpenChange, commands }: SandboxTerminalDialogProps) {
  const isMobile = useIsMobile();

  const scrollRef = React.useRef<HTMLDivElement | null>(null);
  React.useEffect(() => {
    if (!open) return;
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [open, commands]);

  const transcript = (
    <div
      ref={scrollRef}
      className="min-h-0 flex-1 overflow-y-auto bg-black px-4 py-3 font-mono text-xs text-zinc-100"
    >
      {commands.length === 0 ? (
        <p className="text-zinc-500">
          No commands have run yet — they&apos;ll appear here as the agent uses the sandbox.
        </p>
      ) : (
        commands.map((cmd) => (
          <div key={cmd.toolCallId} className="mb-3 whitespace-pre-wrap break-words">
            <div className="text-emerald-400">
              <span className="text-zinc-500">$ </span>
              {cmd.command}
            </div>
            {cmd.status === "running" && !cmd.output ? (
              <div className="mt-1 inline-flex items-center gap-1.5 rounded-sm border border-zinc-700 bg-zinc-900 px-2 py-1 text-zinc-400">
                <Spinner className="size-3 text-zinc-400" />
                running
              </div>
            ) : cmd.output ? (
              <div className="text-zinc-300">{stripAnsi(cmd.output)}</div>
            ) : null}
            {cmd.status === "error" && <div className="text-red-400">command failed</div>}
            {cmd.exitCode != null && cmd.exitCode !== 0 && (
              <div className="text-red-400">[exit {cmd.exitCode}]</div>
            )}
          </div>
        ))
      )}
    </div>
  );

  if (isMobile) {
    return (
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent
          side="bottom"
          className="flex w-full flex-col gap-0 overflow-hidden rounded-t-lg p-0 outline-none data-[side=bottom]:h-[96vh] data-[side=bottom]:min-h-[96vh] data-[side=bottom]:max-h-[96vh]"
        >
          <SheetHeader className="flex shrink-0 flex-row items-center justify-between border-b border-border bg-muted/20 px-4 py-3">
            <SheetTitle className="flex items-center gap-2 text-sm font-semibold tracking-tight">
              <TerminalIcon className="size-4 text-primary" />
              Sandbox Terminal
            </SheetTitle>
          </SheetHeader>
          {transcript}
        </SheetContent>
      </Sheet>
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex h-[80vh] w-[95vw] flex-col gap-0 overflow-hidden p-0 outline-none sm:max-w-4xl">
        <DialogHeader className="flex shrink-0 flex-row items-center justify-between border-b border-border bg-muted/20 px-5 py-3">
          <DialogTitle className="flex items-center gap-2 text-sm font-semibold tracking-tight">
            <TerminalIcon className="size-4 text-primary" />
            Sandbox Terminal
          </DialogTitle>
        </DialogHeader>
        {transcript}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet";
import { useIsMobile } from "@/hooks/use-mobile";
import { ChatMessage } from "./chat-message";
import type { PersonaMessage } from "@personaai/react";

/**
 * Slide-over replaying one subagent (`task` tool call)'s own message
 * timeline — reuses ChatMessage/ToolCallTrace rather than a separate
 * render path, same as NotebookChat.js's SubagentDialog does. On mobile it
 * comes up as a bottom sheet instead of a side drawer — a right-edge
 * drawer at phone widths is basically a full-screen cover with nowhere
 * natural to swipe it away from.
 */
function SubagentSheet({
  open,
  onOpenChange,
  messages,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  messages: PersonaMessage[];
}) {
  const isMobile = useIsMobile();

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side={isMobile ? "bottom" : "right"}
        className="w-full sm:max-w-lg data-[side=bottom]:min-h-[60%] data-[side=bottom]:max-h-[85vh]"
      >
        <SheetHeader className="border-b border-border">
          <SheetTitle>Subagent</SheetTitle>
          <SheetDescription>
            A helper the agent delegated a step to — its own conversation.
          </SheetDescription>
        </SheetHeader>
