"use client";

import * as React from "react";
import { ItemGroup } from "@/components/ui/item";
import { ToolCallCard } from "./tool-call-card";
import { McpAppRenderer } from "./mcp-app-renderer";
import { toolCallStatus } from "./tool-status";
import { useRenderToolCall, type PersonaToolCall, type PersonaTodo } from "@personaai/react";

// TEMP DEBUG — one console line per state change of each tool call, so the
// dev terminal shows whether the backend attached `mcpApp` (mcp_app event)
// or the call streamed without widget metadata.
const loggedToolCalls = new Map<string, string>();

function logToolCall(tc: PersonaToolCall) {
  const hasWidget = !!tc.mcpApp?.resourceUri;
  const status = toolCallStatus(tc);
  const signature = `${status}|${hasWidget ? "widget" : "none"}`;
  if (loggedToolCalls.get(tc.toolCallId) === signature) return;
  loggedToolCalls.set(tc.toolCallId, signature);
  console.info("[mcp-app] tool call", {
    toolCallId: tc.toolCallId,
    toolName: tc.toolName,
    status,
    hasWidget,
    mcpApp: tc.mcpApp,
  });
  if (!hasWidget && tc.toolName.includes("__")) {
    console.warn("[mcp-app] MCP tool call has no widget metadata", {
      toolCallId: tc.toolCallId,
      toolName: tc.toolName,
    });
  }
}

function ToolCallTrace({
  toolCalls,
  todos,
  onOpenSubagent,
  onOpenWorkspaceFile,
  onSendMessage,
}: {
  toolCalls: PersonaToolCall[];
  todos?: PersonaTodo[];
  onOpenSubagent?: (toolCallId: string) => void;
  /** present_file's card calls this when the user clicks its Open button — no longer an auto-fired side effect. */
  onOpenWorkspaceFile?: (path: string) => void;
  onSendMessage?: (text: string) => void;
}) {
  // Custom UIs registered with useRenderTool / useFrontendTool({ render }) /
  // useHumanInTheLoop / useComponent (see frontend-tools.tsx). Called before
  // the early return to keep hook order stable.
  const renderToolCall = useRenderToolCall();

  if (!toolCalls.length) return null;

  // One ItemGroup per run of tool calls. An MCP App block used to flush the
  // current group so it could stand alone, which split a run of consecutive
  // calls into two visually separate clusters around it — it now renders
  // inside the same group, keeping the sequence intact.
  const elements: React.ReactNode[] = [];
  let currentGroup: React.ReactNode[] = [];
  let groupKey: string | undefined;

  const flushGroup = () => {
    if (currentGroup.length === 0) return;
    elements.push(
      <ItemGroup key={`group-${groupKey}`} className="gap-1.5!">
        {currentGroup}
      </ItemGroup>
    );
    currentGroup = [];
    groupKey = undefined;
  };

  for (const tc of toolCalls) {
    logToolCall(tc);
    groupKey ??= tc.toolCallId;
    const customUi = renderToolCall(tc);
    if (customUi) {
      currentGroup.push(
        // p-px: Card draws its outline as `ring-1` (a box-shadow *outside* the
        // box), and the chat scroll viewport clips overflow — flush against its
        // left edge the ring's left side was cut off. 1px of room keeps it.
        <div key={`tool-ui-${tc.toolCallId}`} className="w-full p-px">
          {customUi}
        </div>
      );
    } else if (tc.mcpApp?.resourceUri) {
      currentGroup.push(
        <div key={`mcp-app-${tc.toolCallId}`} className="w-full">
          <McpAppRenderer
            mcpId={tc.mcpApp.mcpId || ""}
            resourceUri={tc.mcpApp.resourceUri || ""}
            toolName={tc.toolName}
            tool={{ args: tc.args, result: tc.result, status: toolCallStatus(tc) }}
            onSendMessage={onSendMessage}
          />
        </div>
      );
    } else {
      currentGroup.push(
        <ToolCallCard
          key={tc.toolCallId}
          toolCall={tc}
          todos={todos}
          onOpenSubagent={onOpenSubagent}
          onOpenFile={onOpenWorkspaceFile}
        />
      );
    }
  }
  flushGroup();

  return <div className="flex flex-col gap-1.5">{elements}</div>;
}

export { ToolCallTrace };

import type { PersonaToolCall } from "@personaai/react";

/**
 * `PersonaToolCall` has no explicit status field (it mirrors the wire
 * protocol: `result` only exists once the call finishes) — this is the one
 * small derivation the visual components need, used everywhere a tool card
 * would otherwise have read a `status` field directly.
 */
export function toolCallStatus(tc: PersonaToolCall): "running" | "done" | "error" {
  if (tc.isError) return "error";
  return tc.result !== undefined ? "done" : "running";
}

"use client";

import * as React from "react";
import {
  ArrowCounterClockwiseIcon,
  ClockIcon,
  CloudFogIcon,
  CloudIcon,
  CloudLightningIcon,
  CloudRainIcon,
  CloudSnowIcon,
  CloudSunIcon,
  DropIcon,
  MapPinIcon,
  PauseIcon,
  PlayIcon,
  SunIcon,
  TimerIcon,
  WindIcon,
} from "@phosphor-icons/react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";

/**
 * Widgets rendered by the frontend tools in frontend-tools.tsx — weather,
 * world clock and countdown timer — plus the weather data fetcher.
 */

// ── Weather (Open-Meteo: free, no API key, CORS-enabled) ────────────────────

export interface WeatherReport {
  place: string;
  current: {
    temperatureC: number;
    feelsLikeC: number;
    humidity: number;
    windKmh: number;
    condition: string;
    code: number;
  };
  daily: { date: string; minC: number; maxC: number; condition: string; code: number }[];
}

// WMO weather interpretation codes (Open-Meteo docs).
function describeWeather(code: number): string {
  if (code === 0) return "Clear sky";
  if (code <= 2) return "Partly cloudy";
  if (code === 3) return "Overcast";
  if (code === 45 || code === 48) return "Fog";
  if (code >= 51 && code <= 57) return "Drizzle";
  if ((code >= 61 && code <= 67) || (code >= 80 && code <= 82)) return "Rain";
  if ((code >= 71 && code <= 77) || code === 85 || code === 86) return "Snow";
  if (code >= 95) return "Thunderstorm";
  return "Unknown";
}

function WeatherIcon({ code, className }: { code: number; className?: string }) {
  const Icon =
    code === 0
      ? SunIcon
      : code <= 2
        ? CloudSunIcon
        : code === 3
          ? CloudIcon
          : code === 45 || code === 48
            ? CloudFogIcon
            : (code >= 71 && code <= 77) || code === 85 || code === 86
              ? CloudSnowIcon
              : code >= 95
                ? CloudLightningIcon
                : CloudRainIcon;
  return <Icon weight="duotone" className={className} />;
}

async function getJson(url: string): Promise<unknown> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Weather service error (${res.status}).`);
  return res.json();
}

function browserPosition(): Promise<{ latitude: number; longitude: number }> {
  return new Promise((resolve, reject) => {
    if (!("geolocation" in navigator)) {
      reject(new Error("This browser can't share its location — ask the user for a city."));
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ latitude: pos.coords.latitude, longitude: pos.coords.longitude }),
      () => reject(new Error("The user didn't share their location — ask them for a city.")),
      { timeout: 10_000, maximumAge: 10 * 60_000 },
    );
  });
}

/** Weather for `city`, or for the browser's location when no city is given. */
export async function fetchWeather(city?: string): Promise<WeatherReport> {
  let latitude: number;
  let longitude: number;
  let place: string;

  const name = city?.trim();
  if (name) {
    const geo = (await getJson(
      `https://geocoding-api.open-meteo.com/v1/search?count=1&language=en&format=json&name=${encodeURIComponent(name)}`,
    )) as { results?: { latitude: number; longitude: number; name: string; admin1?: string; country?: string }[] };
    const hit = geo.results?.[0];
    if (!hit) throw new Error(`Couldn't find a place called "${name}".`);
    ({ latitude, longitude } = hit);
    place = [hit.name, hit.admin1, hit.country].filter(Boolean).join(", ");
  } else {
    ({ latitude, longitude } = await browserPosition());
    place = "Your location";
  }

  const data = (await getJson(
    `https://api.open-meteo.com/v1/forecast?latitude=${latitude}&longitude=${longitude}` +
      "&current=temperature_2m,apparent_temperature,relative_humidity_2m,wind_speed_10m,weather_code" +
      "&daily=weather_code,temperature_2m_max,temperature_2m_min&forecast_days=3&timezone=auto",
  )) as {
    current: {
      temperature_2m: number;
      apparent_temperature: number;
      relative_humidity_2m: number;
      wind_speed_10m: number;
      weather_code: number;
    };
    daily: {
      time: string[];
      weather_code: number[];
      temperature_2m_max: number[];
      temperature_2m_min: number[];
    };
  };

  const round = (n: number) => Math.round(n);
  return {
    place,
    current: {
      temperatureC: round(data.current.temperature_2m),
      feelsLikeC: round(data.current.apparent_temperature),
      humidity: round(data.current.relative_humidity_2m),
      windKmh: round(data.current.wind_speed_10m),
      condition: describeWeather(data.current.weather_code),
      code: data.current.weather_code,
    },
    daily: data.daily.time.map((date, i) => ({
      date,
      minC: round(data.daily.temperature_2m_min[i]),
      maxC: round(data.daily.temperature_2m_max[i]),
      condition: describeWeather(data.daily.weather_code[i]),
      code: data.daily.weather_code[i],
    })),
  };
}

function dayName(date: string, index: number): string {
  if (index === 0) return "Today";
  return new Date(`${date}T12:00:00`).toLocaleDateString(undefined, { weekday: "short" });
}

export function WeatherCard({
  city,
  status,
  result,
  isError,
}: {
  city?: string;
  status: "inProgress" | "executing" | "complete";
