            {/* Centered Zoomed Image */}
            <div className="relative flex max-h-[85vh] max-w-[92vw] items-center justify-center overflow-hidden rounded-2xl bg-black/40 shadow-2xl backdrop-blur-xs ring-1 ring-white/10">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={imageUrl}
                alt={effectivePrompt}
                className="max-h-[82vh] w-auto max-w-[90vw] object-contain select-none"
              />
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import * as React from "react";
import {
  CaretRightIcon,
  CaretDownIcon,
  CopyIcon,
  CheckIcon,
} from "@phosphor-icons/react";
import { cn } from "@/lib/utils";

type JsonValue =
  | string
  | number
  | boolean
  | null
  | undefined
  | JsonValue[]
  | { [key: string]: JsonValue };

function valueClass(value: JsonValue): string {
  if (value === null || value === undefined) return "text-muted-foreground/80 italic";
  switch (typeof value) {
    case "string":
      return "text-amber-600 dark:text-amber-400";
    case "number":
      return "text-blue-600 dark:text-blue-400";
    case "boolean":
      return "text-purple-600 dark:text-purple-400";
    default:
      return "text-foreground";
  }
}

function formatPrimitive(value: JsonValue): string {
  if (value === null) return "null";
  if (value === undefined) return "undefined";
  if (typeof value === "string") return `"${value}"`;
  return String(value);
}

// Collapsed summary preview for objects and arrays
function collapsedPreview(value: JsonValue): string {
  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    const hasComplex = value.some((v) => v !== null && typeof v === "object");
    if (hasComplex) {
      return `Array(${value.length})`;
    }
    const inner = value.map((v) => formatPrimitive(v)).join(", ");
    const text = `[${inner}]`;
    return text.length > 50 ? `[${value.length} items]` : text;
  }

  if (value !== null && typeof value === "object") {
    const keys = Object.keys(value as object);
    if (keys.length === 0) return "{}";
    if (keys.length <= 3) {
      return `{ ${keys.join(", ")} }`;
    }
    return `{ ${keys.length} keys }`;
  }

  return formatPrimitive(value);
}

/** A string that holds a JSON object/array (tool results often do) → that value. */
export function parseJsonString(value: JsonValue): JsonValue | undefined {
  if (typeof value !== "string" || value.length < 2) return undefined;
  const t = value.trim();
  if (!((t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]")))) {
    return undefined;
  }
  try {
    const parsed = JSON.parse(t);
    return parsed !== null && typeof parsed === "object" ? (parsed as JsonValue) : undefined;
  } catch {
    // Attempt recovery for truncated JSON strings
    const clean = t.replace(/…\s*\[(?:truncated|\d+\s*more)[\s\S]*?\]$/, "").trim();
    if (clean.startsWith("{")) {
      let lastIdx = clean.lastIndexOf("}");
      while (lastIdx > 0) {
        try {
          const candidate = clean.slice(0, lastIdx + 1);
          const parsed = JSON.parse(candidate);
          if (parsed && typeof parsed === "object") return parsed as JsonValue;
        } catch {
          // continue
        }
        lastIdx = clean.lastIndexOf("}", lastIdx - 1);
      }
    } else if (clean.startsWith("[")) {
      let lastIdx = clean.lastIndexOf("}");
      while (lastIdx > 0) {
        try {
          const candidate = clean.slice(0, lastIdx + 1) + "]";
          const parsed = JSON.parse(candidate);
          if (Array.isArray(parsed)) return parsed as JsonValue;
        } catch {
          // continue
        }
        lastIdx = clean.lastIndexOf("}", lastIdx - 1);
      }
    }
    return undefined;
  }
}

function CopyNodeButton({ value }: { value: unknown }) {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation();
    const str = typeof value === "string" ? value : JSON.stringify(value, null, 2);
    navigator.clipboard.writeText(str).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1200);
    });
  };

  return (
    <button
      type="button"
      onClick={handleCopy}
      className="opacity-0 group-hover/json-row:opacity-100 transition-opacity ml-1.5 p-0.5 rounded text-muted-foreground/60 hover:text-foreground hover:bg-muted"
      title="Copy value"
    >
      {copied ? <CheckIcon className="size-3 text-emerald-500" /> : <CopyIcon className="size-3" />}
    </button>
  );
}

function JsonNode({
  keyName,
  value,
  depth,
  defaultExpandedDepth = 1,
}: {
  keyName: string | number | null;
  value: JsonValue;
  depth: number;
  defaultExpandedDepth?: number;
}) {
  const parsed = React.useMemo(() => parseJsonString(value), [value]);
  if (parsed !== undefined) {
    return (
      <JsonObjectNode
        keyName={keyName}
        value={parsed}
        depth={depth}
        fromString
        defaultExpandedDepth={defaultExpandedDepth}
      />
    );
  }
  return (
    <JsonObjectNode
      keyName={keyName}
      value={value}
      depth={depth}
      defaultExpandedDepth={defaultExpandedDepth}
    />
  );
}

function JsonObjectNode({
  keyName,
  value,
  depth,
  fromString = false,
  defaultExpandedDepth = 1,
}: {
  keyName: string | number | null;
  value: JsonValue;
  depth: number;
  fromString?: boolean;
  defaultExpandedDepth?: number;
}) {
  const isObject = value !== null && typeof value === "object";
  const isArray = isObject && Array.isArray(value);
  const isEmpty =
    isObject &&
    (isArray ? (value as JsonValue[]).length === 0 : Object.keys(value as object).length === 0);

  // Depth 0 or depths less than defaultExpandedDepth start expanded
  const [open, setOpen] = React.useState(depth < defaultExpandedDepth);

  // Leaf node (primitive or empty array/object)
  if (!isObject || isEmpty) {
    return (
      <div className="group/json-row flex items-baseline gap-1.5 py-0.5 px-1 -mx-1 rounded hover:bg-muted/40 font-mono text-[11px] leading-relaxed transition-colors">
        {/* Fixed gutter spacer matching caret button so keys align vertically */}
        <span className="size-3.5 shrink-0" aria-hidden="true" />
        {keyName != null && (
          <span className="shrink-0 font-medium text-foreground/80 select-text">
            {typeof keyName === "number" ? (
              <span className="text-muted-foreground/60 font-normal">[{keyName}]</span>
            ) : (
              keyName
            )}
            :
          </span>
        )}
        <span
          className={cn(
            "break-words whitespace-pre-wrap [overflow-wrap:anywhere] select-text",
            isEmpty ? "text-muted-foreground/70" : valueClass(value)
          )}
        >
          {isEmpty ? (isArray ? "[]" : "{}") : formatPrimitive(value)}
        </span>
        <CopyNodeButton value={value} />
      </div>
    );
  }

  const entries: [string | number, JsonValue][] = isArray
    ? (value as JsonValue[]).map((v, i) => [i, v])
    : Object.entries(value as object);

  return (
    <div className="font-mono text-[11px] leading-relaxed">
      <div
        onClick={() => setOpen((v) => !v)}
        className="group/json-row flex w-full items-baseline gap-1.5 py-0.5 px-1 -mx-1 rounded hover:bg-muted/40 text-left cursor-pointer transition-colors"
      >
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            setOpen((v) => !v);
          }}
          className="flex size-3.5 items-center justify-center shrink-0 rounded text-muted-foreground/70 hover:text-foreground hover:bg-muted/80 transition-colors"
          aria-label={open ? "Collapse" : "Expand"}
        >
          {open ? <CaretDownIcon className="size-3" /> : <CaretRightIcon className="size-3" />}
        </button>

        <span className="break-all select-text flex items-baseline gap-1.5 min-w-0">
          {keyName != null && (
            <span className="font-medium text-foreground/80 shrink-0">
              {typeof keyName === "number" ? (
                <span className="text-muted-foreground/60 font-normal">[{keyName}]</span>
              ) : (
                keyName
              )}
              :
            </span>
          )}

          {fromString && (
            <span
              className="rounded bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 px-1 py-0.2 text-[9px] font-sans font-medium uppercase select-none"
              title="This value was a JSON string, shown decoded"
            >
              JSON
            </span>
          )}

          {open ? (
            <span className="text-muted-foreground/70 font-mono">{isArray ? "[" : "{"}</span>
          ) : (
            <span className="text-muted-foreground/70 font-mono italic">
              {collapsedPreview(value)}
            </span>
          )}
        </span>

        <CopyNodeButton value={value} />
      </div>

      {open && (
        <div className="ml-1.5 border-l border-border/50 dark:border-border/40 pl-2.5 flex flex-col gap-0.5">
          {entries.map(([k, v]) => (
            <JsonNode
              key={k}
              keyName={isArray ? k : k}
              value={v}
              depth={depth + 1}
              defaultExpandedDepth={defaultExpandedDepth}
            />
          ))}
        </div>
      )}

      {open && (
        <div className="flex items-center gap-1.5 px-1 -mx-1 text-muted-foreground/70 font-mono">
          <span className="size-3.5 shrink-0" aria-hidden="true" />
          <span>{isArray ? "]" : "}"}</span>
        </div>
      )}
    </div>
  );
}

/**
 * Collapsible, syntax-colored JSON tree.
 * - Leaf rows and expandable rows share a consistent gutter for vertical key alignment.
 * - Top-level keys start expanded; nested structures show clean previews with item counts.
 * - JSON strings inside properties are automatically decoded and badged.
 * - Row hover allows copying individual values or JSON objects.
 */
export function JsonTreeView({
  data: raw,
  className,
  defaultExpandedDepth = 1,
}: {
  data: unknown;
  className?: string;
  defaultExpandedDepth?: number;
}) {
  const decoded = React.useMemo(() => parseJsonString(raw as JsonValue), [raw]);
  const data = decoded ?? raw;

  if (data === null || typeof data !== "object") {
    return (
      <div className={cn("font-mono text-[11px]", valueClass(data as JsonValue), className)}>
        {formatPrimitive(data as JsonValue)}
      </div>
    );
  }

  const entries: [string | number, JsonValue][] = Array.isArray(data)
    ? data.map((v, i) => [i, v])
    : Object.entries(data as object);

  if (entries.length === 0) {
    return (
      <div className={cn("font-mono text-[11px] text-muted-foreground/70", className)}>
        {Array.isArray(data) ? "[]" : "{}"}
      </div>
    );
  }

  return (
    <div className={cn("font-mono text-[11px] leading-relaxed select-text", className)}>
      {entries.map(([k, v]) => (
        <JsonNode
          key={k}
          keyName={Array.isArray(data) ? k : k}
          value={v}
          depth={0}
          defaultExpandedDepth={defaultExpandedDepth}
        />
      ))}
    </div>
  );
}

"use client";

import * as React from "react";
import {
  FileTextIcon,
  FileCodeIcon,
  FolderIcon,
  FolderOpenIcon,
  CaretRightIcon,
  CaretDownIcon,
} from "@phosphor-icons/react";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Empty, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty";
import { parseToolArgs, parseLsResults, buildLsTree, type LsTreeNode } from "./utils";
import type { PersonaToolCall } from "@personaai/react";
import { toolCallStatus } from "../tool-status";

// Same file-vs-code icon split file-explorer-editor.tsx uses, so a listed
// entry reads the same way whether you're looking at it in the Explorer
// sidebar or in an `ls` tool call's result.
function fileIcon(name: string) {
  const ext = name.split(".").pop()?.toLowerCase();
  if (ext === "md" || ext === "markdown" || ext === "txt") {
    return <FileTextIcon className="size-3.5 shrink-0 text-muted-foreground" />;
  }
  return <FileCodeIcon className="size-3.5 shrink-0 text-muted-foreground" />;
}

// One tree row, recursive — a directory node is its own caret+folder toggle
// (icon swaps open/closed) with its children indented underneath; a file
// node is a plain leaf row. Mirrors file-explorer-editor.tsx's per-folder
// expand/collapse instead of a single flat list.
function TreeRow({ node, depth, collapsed, onToggle }: {
  node: LsTreeNode;
  depth: number;
  collapsed: Set<string>;
  onToggle: (path: string) => void;
}) {
  const indent = { paddingLeft: `${8 + depth * 14}px` };

  if (!node.isDir) {
    return (
      <div
        style={indent}
        className="flex min-w-0 items-center gap-1.5 py-1 pr-2 text-xs text-muted-foreground hover:bg-muted/40 hover:text-foreground"
      >
        {fileIcon(node.name)}
        <span className="whitespace-nowrap font-mono">{node.name}</span>
      </div>
    );
  }

  // Open by default — a node is only closed once the user explicitly
  // collapses it, so a result that streams in after mount (or gains new
  // top-level entries) doesn't need its own "start expanded" bookkeeping.
  const isOpen = !collapsed.has(node.path);
  return (
    <div className="flex flex-col">
      <Button
        type="button"
        variant="ghost"
        style={indent}
        onClick={() => onToggle(node.path)}
        className="h-auto w-full min-w-0 justify-start gap-1 rounded-none py-1 pr-2 text-left text-xs font-normal text-muted-foreground"
      >
        {isOpen ? <CaretDownIcon className="size-3 shrink-0" /> : <CaretRightIcon className="size-3 shrink-0" />}
        {isOpen ? <FolderOpenIcon className="size-3.5 shrink-0" /> : <FolderIcon className="size-3.5 shrink-0" />}
        <span className="whitespace-nowrap font-mono">{node.name}</span>
      </Button>
      {isOpen &&
        node.children?.map((child) => (
          <TreeRow key={child.path} node={child} depth={depth + 1} collapsed={collapsed} onToggle={onToggle} />
        ))}
    </div>
  );
}

// Renders like file-explorer-editor.tsx's Explorer tree: a caret toggle for
// the listing itself, a folder icon that swaps open/closed, and — since an
// `ls` entry can carry slashes ("/memories/agent/") the flat listing never
// groups on its own — a real nested tree underneath where every directory
// is its own independently expandable node.
export function LsDirectoryCard({ toolCall }: { toolCall: PersonaToolCall }) {
  const args = parseToolArgs(toolCall.args) || {};
  const path = (args.path as string) || (args.dir as string) || (args.directory as string) || "/";
  const items = parseLsResults(toolCall.result);
  const tree = React.useMemo(() => buildLsTree(items), [items]);
  const done = toolCallStatus(toolCall) !== "running";
  // Starts expanded — this card only renders once the outer tool-call card
  // is already open, so a second click just to see the listing would be
  // redundant. The toggle exists for re-collapsing a long listing.
  const [open, setOpen] = React.useState(true);
  const [collapsedPaths, setCollapsedPaths] = React.useState<Set<string>>(() => new Set());

  const toggleNode = (nodePath: string) => {
    setCollapsedPaths((prev) => {
      const next = new Set(prev);
      if (next.has(nodePath)) next.delete(nodePath);
      else next.add(nodePath);
      return next;
    });
  };

  return (
    <div className="flex min-w-0 flex-col overflow-hidden border border-border">
      <Button
        type="button"
        variant="ghost"
        onClick={() => setOpen((v) => !v)}
        className="h-auto w-full min-w-0 justify-start gap-1.5 rounded-none bg-muted/10 px-2 py-1.5 text-left text-[11px] font-semibold uppercase tracking-wider text-muted-foreground"
      >
        {open ? <CaretDownIcon className="size-3 shrink-0" /> : <CaretRightIcon className="size-3 shrink-0" />}
        {open ? <FolderOpenIcon className="size-3.5 shrink-0" /> : <FolderIcon className="size-3.5 shrink-0" />}
        <span className="min-w-0 truncate font-mono normal-case">{path}</span>
      </Button>
      {open &&
        (!done ? (
          <div className="flex flex-col gap-1.5 p-2">
            <Skeleton className="h-5 w-3/4" />
            <Skeleton className="h-5 w-1/2" />
            <Skeleton className="h-5 w-2/3" />
          </div>
        ) : tree.length > 0 ? (
          // A folder tree can run both long (many siblings) and wide (deep
          // nesting pushes indentation out, long names) — rows use
          // whitespace-nowrap rather than truncating, so nothing is ever
          // silently clipped; min-w-0 (threaded down through every row) is
          // what stops that width from forcing this card wider than its
          // container instead of just scrolling within it.
          // NOTE(chat-sdk sandbox): the real `orientation="both"` prop this
          // called for needs platform's own customized ScrollArea (not in
          // the shadcn registry's registryDependencies) — dropped locally
          // here so this vendored copy builds against the generic base
          // ScrollArea; see the chat-sdk PR description for the upstream fix.
          <ScrollArea className="max-h-56 min-w-0">
            <div className="flex min-w-0 flex-col py-1">
              {tree.map((node) => (
                <TreeRow key={node.path} node={node} depth={0} collapsed={collapsedPaths} onToggle={toggleNode} />
              ))}
            </div>
          </ScrollArea>
        ) : (
          <Empty className="p-4">
            <EmptyHeader>
              <EmptyMedia variant="icon">
                <FolderIcon />
              </EmptyMedia>
              <EmptyTitle className="text-xs">Empty directory</EmptyTitle>
            </EmptyHeader>
          </Empty>
        ))}
    </div>
  );
}

"use client";

import { FileCodeIcon, FileTextIcon } from "@phosphor-icons/react";
import { Spinner } from "@/components/ui/spinner";
import { getReadFileToolDetails, CODE_EXTENSIONS, fileExtOf } from "./utils";
import type { PersonaToolCall } from "@personaai/react";
import { toolCallStatus } from "../tool-status";

// Split file content into display lines + line numbers, stripping any
// "   1  content" prefixes the tool may have added.
function processLines(content: string, lineOffset: number) {
  if (!content) return { lines: [] as string[], lineNumbers: [] as number[] };
  const rawLines = content.split("\n");
  if (rawLines.length > 1 && rawLines[rawLines.length - 1] === "") {
    rawLines.pop();
  }

  let isPrefixed = true;
  const regex = /^\s*(\d+)(?:\s+(.*)|$)/;

  for (const line of rawLines) {
    if (line.trim() === "") continue;
    if (!regex.test(line)) {
      isPrefixed = false;
      break;
    }
  }

  if (isPrefixed && rawLines.length > 0) {
    const cleaned: string[] = [];
    const numbers: number[] = [];
    let lastNum = 0;

    for (const line of rawLines) {
      const match = line.match(regex);
      if (match) {
        cleaned.push(match[2] || "");
        lastNum = parseInt(match[1], 10);
        numbers.push(lastNum);
      } else {
        cleaned.push(line);
        lastNum += 1;
        numbers.push(lastNum);
      }
    }
    return { lines: cleaned, lineNumbers: numbers };
  }

  const offset = lineOffset || 0;
  const numbers = rawLines.map((_, i) => offset + i + 1);
  return { lines: rawLines, lineNumbers: numbers };
}

export function ReadFileCard({ toolCall }: { toolCall: PersonaToolCall }) {
  const details = getReadFileToolDetails(toolCall.args, toolCall.result);
  const content = details?.content ?? "";
  const otherArgs = details?.otherArgs ?? {};
  const filePath = details?.filePath ?? "";
  const lineOffset = (otherArgs.offset as number) ?? (otherArgs.offsetLine as number) ?? 0;

  const { lines, lineNumbers } = processLines(content, lineOffset);

  if (!details) {
    return (
      <pre className="max-h-56 overflow-auto whitespace-pre-wrap break-words font-mono text-xs leading-5 text-foreground bg-muted p-2.5 rounded-none border border-border">
        {toolCall.result || "No result yet."}
      </pre>
    );
  }

  const fileName = filePath.split("/").pop() || filePath;
  const isCode = CODE_EXTENSIONS.includes(fileExtOf(fileName));
  const FileIcon = isCode ? FileCodeIcon : FileTextIcon;
  const done = toolCallStatus(toolCall) !== "running";

  return (
    <div className="flex flex-col rounded-none border border-border bg-card overflow-hidden">
      <div className="flex items-center justify-between border-b border-border bg-muted/50 px-3 py-2">
        <div className="flex items-center gap-2 min-w-0">
          <FileIcon className="size-4 shrink-0 text-muted-foreground" />
          <span className="truncate text-xs font-semibold text-foreground font-mono">{filePath}</span>
        </div>
      </div>

      {!done ? (
        <div className="flex flex-col items-center justify-center py-8 text-center text-muted-foreground">
          <Spinner className="size-5 mb-2 text-primary" />
          <span className="text-[11px] font-bold uppercase tracking-wider">Reading file content…</span>
        </div>
      ) : content ? (
        <div className="relative max-h-72 overflow-auto bg-[#0D1117] font-mono text-[11.5px] text-[#C9D1D9]">
          <div className="flex min-w-full">
            <div className="w-10 shrink-0 select-none border-r border-[#30363D] bg-[#161B22]/50 py-3 text-right pr-3 text-[10px] font-bold text-[#8B949E]">
              {lineNumbers.map((num, i) => (
                <div key={i} className="h-5 leading-5">
                  {num}
                </div>
              ))}
            </div>
            <div className="flex-1 py-3 pl-3 pr-4 overflow-x-auto select-text">
              {lines.map((line, i) => (
                <pre key={i} className="h-5 leading-5 whitespace-pre font-mono text-[#E6EDF2]">
                  {line || " "}
                </pre>
              ))}
            </div>
          </div>
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-8 text-center text-muted-foreground">
          <FileTextIcon className="size-7 mb-2" />
          <span className="text-[11px] font-bold uppercase tracking-wider">Empty file or no content</span>
        </div>
      )}

      {done && content && (
        <div className="flex items-center justify-between border-t border-border bg-muted/50 px-3 py-2 text-[10px] font-bold text-muted-foreground uppercase tracking-tight select-none">
          <div>
            Showing lines {lineNumbers[0]}-{lineNumbers[lineNumbers.length - 1]}
          </div>
          <div>{lines.length} lines</div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { CopyIcon, CheckIcon } from "@phosphor-icons/react";
import { tryParseJson } from "./utils";
import { JsonTreeView } from "./json-tree-view";
import { cn } from "@/lib/utils";

/**
 * A labeled "Input" / "Result" panel: a collapsible JSON tree (falls back to
 * plain text for non-JSON results), with a copy-to-clipboard button. Renders
 * the full tree with no height cap - nodes collapse individually instead of
 * the whole panel scrolling.
 */
export function RequestResponsePanel({
  label,
  text,
  isError,
  className,
}: {
  label: string;
  text: string | undefined;
  isError?: boolean;
  className?: string;
}) {
  const [copied, setCopied] = React.useState(false);

  const parsed = tryParseJson(text);
  const isJson = parsed !== null && typeof parsed === "object";

  if (!text) return null;

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(isJson ? JSON.stringify(parsed, null, 2) : text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      // clipboard access denied — nothing to surface, the button just won't flip
    }
  };

  return (
    <div>
      <div className="mb-1 flex items-center justify-between">
        <div className="text-xs font-semibold text-muted-foreground">{label}</div>
        <button
          type="button"
          onClick={handleCopy}
          className="flex items-center gap-1 text-[10px] font-semibold text-muted-foreground hover:text-foreground"
        >
          {copied ? <CheckIcon className="size-3" /> : <CopyIcon className="size-3" />}
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
      <div
        className={cn(
          "max-h-40 overflow-auto rounded-none border p-2",
          isError ? "border-destructive/30 bg-destructive/10" : "border-border bg-muted",
          className
        )}
      >
        {isJson ? (
          <JsonTreeView data={parsed} />
        ) : (
          <div
            className={cn(
              "whitespace-pre-wrap break-words font-mono text-[11px] leading-relaxed",
              isError ? "text-destructive" : "text-foreground"
            )}
          >
            {text}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  GlobeIcon,
  MagnifyingGlassIcon,
  ShieldCheckIcon,
} from "@phosphor-icons/react";
import { Spinner } from "@/components/ui/spinner";
import { cn } from "@/lib/utils";
import { tryParseJson } from "./utils";
import type { PersonaToolCall } from "@personaai/react";

export interface SearchResultItem {
  title: string;
  url: string;
  snippet?: string;
  domain: string;
}

export function formatDisplayDomain(urlOrDomain: string): string {
  try {
    let hostname = urlOrDomain;
    if (urlOrDomain.startsWith("http://") || urlOrDomain.startsWith("https://")) {
      hostname = new URL(urlOrDomain).hostname;
    }
    // Remove www.
    hostname = hostname.replace(/^www\./, "");
    // Remove common generic top-level domains: e.g. .com, .org, .net, .io, etc.
    // developers.google.com -> developers.google, theconversation.com -> theconversation, wired.com -> wired
    const cleaned = hostname.replace(/\.(com|org|net|io|edu|gov|app|dev|co)$/i, "");
    return cleaned || hostname;
  } catch {
    return urlOrDomain;
  }
}

function extractDomain(urlStr: string): string {
  try {
    const parsed = new URL(urlStr);
    return parsed.hostname.replace(/^www\./, "");
  } catch {
    return urlStr;
  }
}

export function parseSearchResults(
  rawResult: unknown,
  rawArgs: unknown
): { query: string; results: SearchResultItem[] } {
  let query = "";
  if (rawArgs) {
    const argsObj =
      typeof rawArgs === "string"
        ? (tryParseJson(rawArgs) as Record<string, unknown>)
        : (rawArgs as Record<string, unknown>);
    if (argsObj?.query && typeof argsObj.query === "string") {
      query = argsObj.query;
    }
  }

  const results: SearchResultItem[] = [];

  if (!rawResult) {
    return { query, results };
  }

  const parsed = typeof rawResult === "string" ? tryParseJson(rawResult) : rawResult;

  // Case 1: Object with results array: { query, results: [...] } or array of results
  if (parsed && typeof parsed === "object") {
    const obj = parsed as Record<string, unknown>;
    if (typeof obj.query === "string" && !query) {
      query = obj.query;
    }
    const list = Array.isArray(obj.results)
      ? obj.results
      : Array.isArray(parsed)
        ? parsed
        : null;

    if (list) {
      for (const item of list) {
        if (item && typeof item === "object") {
          const it = item as Record<string, unknown>;
          const url =
            (typeof it.url === "string"
              ? it.url
              : typeof it.link === "string"
                ? it.link
                : "") || "";
          const title =
            (typeof it.title === "string"
              ? it.title
              : typeof it.name === "string"
                ? it.name
                : "") || extractDomain(url) || "Web Page";
          const snippet =
            (typeof it.content === "string"
              ? it.content
              : typeof it.snippet === "string"
                ? it.snippet
                : "") || "";

          if (url) {
            results.push({
              title,
              url,
              snippet,
              domain: extractDomain(url),
            });
          }
        }
      }
      if (results.length > 0) return { query, results };
    }
  }

  // Case 2: String containing URLs or markdown links
  if (typeof rawResult === "string") {
    const urlRegex = /(https?:\/\/[^\s"'<>\)]+)/g;
    const lines = rawResult.split("\n");
    let currentTitle = "";
    for (const line of lines) {
      const trimmed = line.trim();
      const match = urlRegex.exec(trimmed);
      if (match) {
        const url = match[1];
        const title = currentTitle || extractDomain(url);
        results.push({
          title,
          url,
          domain: extractDomain(url),
        });
        currentTitle = "";
      } else if (trimmed.length > 3 && !trimmed.startsWith("{") && !trimmed.startsWith("[")) {
        currentTitle = trimmed.replace(/^[-*•\d.]+\s*/, "");
      }
      urlRegex.lastIndex = 0;
    }
  }

  return { query, results };
}

export function SearchCitationCard({
  toolCall,
  isPending,
  defaultOpen = true,
}: {
  toolCall: PersonaToolCall | { toolName?: string; name?: string; args?: string; result?: string };
  isPending?: boolean;
  defaultOpen?: boolean;
}) {
  const [open, setOpen] = React.useState(defaultOpen);
  const [showAll, setShowAll] = React.useState(false);

  const { query, results } = React.useMemo(
    () => parseSearchResults(toolCall.result, toolCall.args),
    [toolCall.result, toolCall.args]
  );

  const visibleResults = showAll ? results : results.slice(0, 3);
  const hasMore = results.length > 3;

  return (
    <div className="flex w-full flex-col text-foreground transition-all">
      {/* Header Bar - Frameless & Flush */}
      <button
        type="button"
        onClick={() => setOpen((prev) => !prev)}
        className="group/btn flex items-center py-0.5 text-left cursor-pointer transition-colors text-foreground select-none"
      >
        <span className="text-xs font-medium text-foreground">
          {isPending ? "Searching the web" : "Searched the web"}
        </span>
      </button>

      {/* Expanded Content - Indented Under Header, Zero Left Padding on Items */}
      {open && (
        <div className="flex flex-col pl-5 mt-1 space-y-1">
          {/* Query Row - Aligned with Favicons */}
          {query && (
            <div className="flex items-center gap-2.5 py-0.5 text-xs text-muted-foreground">
              <div className="flex size-4 shrink-0 items-center justify-center">
                <MagnifyingGlassIcon className="size-3.5 shrink-0 text-muted-foreground/70" />
              </div>
              <span className="truncate font-normal text-foreground/85">{query}</span>
            </div>
          )}

          {/* Pending Skeleton Loader */}
          {isPending && results.length === 0 && (
            <div className="flex flex-col gap-1.5 py-1">
              <div className="h-3 w-4/5 animate-pulse rounded-xs bg-muted/60" />
              <div className="h-3 w-3/5 animate-pulse rounded-xs bg-muted/40" />
            </div>
          )}

          {/* Search Result Items - Zero Left Padding Before Favicon */}
          {results.length > 0 && (
            <div className="flex flex-col">
              {visibleResults.map((item, idx) => (
                <a
                  key={`${item.url}-${idx}`}
                  href={item.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="group/item flex items-center gap-2.5 py-1 text-xs text-foreground/90 transition-colors hover:text-foreground"
                  title={item.title}
                >
                  {/* Favicon or fallback - starts completely flush with zero left padding */}
                  <div className="flex size-4 shrink-0 items-center justify-center overflow-hidden rounded-xs">
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={`https://www.google.com/s2/favicons?domain=${encodeURIComponent(item.domain || "")}&sz=32`}
                      alt=""
                      className="size-3.5 object-contain"
                      onError={(e) => {
                        e.currentTarget.style.display = "none";
                        const fallback = e.currentTarget.nextElementSibling as HTMLElement | null;
                        if (fallback) fallback.style.display = "flex";
                      }}
                    />
                    <GlobeIcon className="hidden size-3.5 text-muted-foreground" />
                  </div>

                  {/* Title */}
                  <span className="min-w-0 flex-1 truncate font-normal group-hover/item:text-primary transition-colors">
                    {item.title}
                  </span>

                  {/* Domain Tag & Shield Icon */}
                  <span className="shrink-0 flex items-center gap-1 text-[11px] text-muted-foreground/75">
                    <span>{formatDisplayDomain(item.domain || item.url)}</span>
                    <ShieldCheckIcon className="size-3 shrink-0 text-muted-foreground/60 group-hover/item:text-primary/70 transition-colors" />
                  </span>
                </a>
              ))}

              {/* Show more / Show less toggle */}
              {hasMore && (
                <button
                  type="button"
                  onClick={() => setShowAll((prev) => !prev)}
                  className="pt-0.5 flex items-center py-1 text-xs font-normal text-muted-foreground transition-colors hover:text-foreground cursor-pointer select-none"
                >
                  <span>{showAll ? "Show less" : `+${results.length - 3} more`}</span>
                </button>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

interface Point {
  x: number;
  y: number;
}

const GRID_SIZE = 20;
const INITIAL_SNAKE: Point[] = [
  { x: 10, y: 10 },
  { x: 9, y: 10 },
  { x: 8, y: 10 },
];
const INITIAL_DIR: Point = { x: 1, y: 0 };

export function SnakeMiniGame() {
  const canvasRef = React.useRef<HTMLCanvasElement | null>(null);

  // Mutable game state held in refs for 60fps tick stability
  const gameState = React.useRef({
    snake: [...INITIAL_SNAKE],
    dir: { ...INITIAL_DIR },
    nextDir: { ...INITIAL_DIR },
    food: { x: 15, y: 10 },
    flashUntil: 0,
  });

  const spawnFood = React.useCallback((currentSnake: Point[]) => {
    let newFood: Point;
    let collision: boolean;
    do {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE),
      };
      // eslint-disable-next-line @typescript-eslint/no-loop-func
      collision = currentSnake.some((seg) => seg.x === newFood.x && seg.y === newFood.y);
    } while (collision);
    return newFood;
  }, []);

  const resetGame = React.useCallback(
    (now: number) => {
      const freshFood = spawnFood(INITIAL_SNAKE);
      gameState.current = {
        snake: [...INITIAL_SNAKE],
        dir: { ...INITIAL_DIR },
        nextDir: { ...INITIAL_DIR },
        food: freshFood,
        flashUntil: now + 200,
      };
    },
    [spawnFood]
  );

  // Keyboard controls
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const { dir } = gameState.current;

      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(e.code)) {
        e.preventDefault();
      }

      switch (e.code) {
        case "ArrowUp":
        case "KeyW":
          if (dir.y === 0) gameState.current.nextDir = { x: 0, y: -1 };
          break;
        case "ArrowDown":
        case "KeyS":
          if (dir.y === 0) gameState.current.nextDir = { x: 0, y: 1 };
          break;
        case "ArrowLeft":
        case "KeyA":
          if (dir.x === 0) gameState.current.nextDir = { x: -1, y: 0 };
          break;
        case "ArrowRight":
        case "KeyD":
          if (dir.x === 0) gameState.current.nextDir = { x: 1, y: 0 };
          break;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Touch swipe controls
  const touchStartRef = React.useRef<{ x: number; y: number } | null>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length > 0) {
      touchStartRef.current = {
        x: e.touches[0].clientX,
        y: e.touches[0].clientY,
      };
    }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (!touchStartRef.current) return;
    const { dir } = gameState.current;

    const touchEnd = {
      x: e.changedTouches[0].clientX,
      y: e.changedTouches[0].clientY,
    };
    const dx = touchEnd.x - touchStartRef.current.x;
    const dy = touchEnd.y - touchStartRef.current.y;
    touchStartRef.current = null;

    if (Math.abs(dx) > Math.abs(dy)) {
      if (dx > 15 && dir.x === 0) gameState.current.nextDir = { x: 1, y: 0 };
      else if (dx < -15 && dir.x === 0) gameState.current.nextDir = { x: -1, y: 0 };
    } else {
      if (dy > 15 && dir.y === 0) gameState.current.nextDir = { x: 0, y: 1 };
      else if (dy < -15 && dir.y === 0) gameState.current.nextDir = { x: 0, y: -1 };
    }
  };

  // Main game tick and render loop
  React.useEffect(() => {
    let animId: number;
    let lastTick = 0;
    const TICK_INTERVAL = 100; // ms per move

    const loop = (timestamp: number) => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      // Ensure canvas pixel dimensions match client rect perfectly
      if (canvas.clientWidth && canvas.clientHeight) {
        if (canvas.width !== canvas.clientWidth || canvas.height !== canvas.clientHeight) {
          canvas.width = canvas.clientWidth;
          canvas.height = canvas.clientHeight;
        }
      }

      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const width = canvas.width;
      const height = canvas.height;
      const cellW = width / GRID_SIZE;
      const cellH = height / GRID_SIZE;

      if (timestamp - lastTick >= TICK_INTERVAL) {
        lastTick = timestamp;
        const state = gameState.current;

        state.dir = state.nextDir;
        const head = state.snake[0];
        let nextX = head.x + state.dir.x;
        let nextY = head.y + state.dir.y;

        // Wrap around edges
        if (nextX < 0) nextX = GRID_SIZE - 1;
        if (nextX >= GRID_SIZE) nextX = 0;
        if (nextY < 0) nextY = GRID_SIZE - 1;
        if (nextY >= GRID_SIZE) nextY = 0;

        // Self collision check -> smooth reset
        const hitSelf = state.snake.slice(0, -1).some((seg) => seg.x === nextX && seg.y === nextY);

        if (hitSelf) {
          resetGame(timestamp);
        } else {
          const newHead: Point = { x: nextX, y: nextY };
          const newSnake = [newHead, ...state.snake];

          // Food collision
          if (nextX === state.food.x && nextY === state.food.y) {
            state.food = spawnFood(newSnake);
          } else {
            newSnake.pop();
          }
          state.snake = newSnake;
        }
      }

      // Render Frame
      const state = gameState.current;
      const isDark =
        typeof document !== "undefined" &&
        (document.documentElement.classList.contains("dark") || !!canvas.closest(".dark"));
      // Platform design system color: luminous white in dark mode, platform primary indigo in light mode (no harsh black)
      const primaryRgb = isDark ? "255, 255, 255" : "79, 70, 229";
      const gridRgb = isDark ? "255, 255, 255" : "148, 163, 184";

      ctx.clearRect(0, 0, width, height);

      // 1. Defined background dot grid flush to border
      ctx.fillStyle = `rgba(${gridRgb}, ${isDark ? 0.12 : 0.2})`;
      for (let x = 0; x < GRID_SIZE; x++) {
        for (let y = 0; y < GRID_SIZE; y++) {
          ctx.beginPath();
          ctx.arc(
            x * cellW + cellW / 2,
            y * cellH + cellH / 2,
            1.8,
            0,
            Math.PI * 2
          );
          ctx.fill();
        }
      }

      // 2. Food - prominent platform glowing circular dot
      const foodX = state.food.x * cellW + cellW / 2;
      const foodY = state.food.y * cellH + cellH / 2;
      const pulse = Math.sin(timestamp * 0.007) * 1.2;

      ctx.shadowBlur = 10;
      ctx.shadowColor = `rgba(${primaryRgb}, ${isDark ? 0.9 : 0.5})`;
      ctx.fillStyle = isDark ? "#ffffff" : `rgb(${primaryRgb})`;
      ctx.beginPath();
      ctx.arc(foodX, foodY, Math.max(3.5, Math.min(cellW, cellH) / 2.3 + pulse), 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;

      // 3. Snake - rendered as circular DOTS matching the dot matrix (NO blocks / NO rectangles)
      state.snake.forEach((seg, index) => {
        const isHead = index === 0;
        const cx = seg.x * cellW + cellW / 2;
        const cy = seg.y * cellH + cellH / 2;
        const minDim = Math.min(cellW, cellH);
        const radius = isHead
          ? Math.max(3.8, minDim * 0.4)
          : Math.max(2.8, minDim * 0.32);

        if (isHead) {
          ctx.shadowBlur = 8;
          ctx.shadowColor = `rgba(${primaryRgb}, ${isDark ? 0.95 : 0.6})`;
          ctx.fillStyle = isDark ? "#ffffff" : `rgb(${primaryRgb})`;
        } else {
          ctx.shadowBlur = 0;
          const alpha = Math.max(0.35, 0.9 - index * 0.04);
          ctx.fillStyle = `rgba(${primaryRgb}, ${alpha})`;
        }

        ctx.beginPath();
        ctx.arc(cx, cy, radius, 0, Math.PI * 2);
        ctx.fill();
      });

      animId = requestAnimationFrame(loop);
    };

    animId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animId);
  }, [resetGame, spawnFood]);

  return (
    <div
      className="relative flex size-full items-center justify-center overflow-hidden rounded-2xl bg-muted/40 text-foreground select-none"
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      <canvas
        ref={canvasRef}
        className="size-full block"
      />
    </div>
  );
}

export function tryParseJson(value: string | undefined | null): unknown {
  if (!value || typeof value !== "string") return null;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

// Tool arguments can arrive double-encoded — LangChain's tool tracer wraps
// stringified args as { input: "<json>" }. Unwrap that envelope so callers
// see the real args (file_path, old_string, todos, ...). Safe on clean args.
export function parseToolArgs(argsText: string | undefined): Record<string, unknown> | null {
  const parsed = tryParseJson(argsText) as Record<string, unknown> | null;
  if (parsed && typeof parsed.input === "string" && Object.keys(parsed).length === 1) {
    return (tryParseJson(parsed.input) as Record<string, unknown> | null) ?? parsed;
  }
  return parsed;
}

const PATH_KEYS = [
  "file_path",
  "filePath",
  "path",
  "filename",
  "fileName",
  "targetFile",
  "TargetFile",
  "target_file",
];

function findPath(args: Record<string, unknown>): string {
  for (const key of PATH_KEYS) {
    if (typeof args[key] === "string") return args[key] as string;
  }
  return "";
}

export function isLsTool(name: string | undefined): boolean {
  if (!name) return false;
  const lower = name.toLowerCase();
  return (
    lower === "ls" ||
    lower === "list_dir" ||
    lower === "list_directory" ||
    lower.includes("list_dir") ||
    lower.includes("list_directory")
  );
}

export function isReadFileTool(name: string | undefined): boolean {
  if (!name) return false;
  const lower = name.toLowerCase();
  return (
    lower === "read_file" ||
    lower === "view_file" ||
    lower.includes("read_file") ||
    lower.includes("view_file")
  );
}

export function isFileWriteTool(name: string | undefined): boolean {
  return (name || "").toLowerCase() === "write_file";
}

export function isFileEditTool(name: string | undefined): boolean {
  return (name || "").toLowerCase() === "edit_file";
}

export function isGrepTool(name: string | undefined): boolean {
  return (name || "").toLowerCase().includes("grep");
}

export function isSearchTool(name: string | undefined): boolean {
  if (!name) return false;
  const lower = name.toLowerCase();
  return (
    lower === "search_web" ||
    lower === "web_search" ||
    lower === "search" ||
    lower === "tavily_search" ||
    lower === "brave_search" ||
    lower.includes("search_web") ||
    lower.includes("web_search")
  );
}

export interface LsEntry {
  name: string;
  isDir: boolean;
}

export function parseLsResults(resultText: string | undefined): LsEntry[] {
  if (!resultText) return [];

  const parsed = tryParseJson(resultText);
  if (Array.isArray(parsed)) {
    return parsed.map((item) => {
      if (typeof item === "string") {
        const isDir = item.endsWith("/") || item.includes("(directory)");
        return { name: item.replace(/\(directory\)/g, "").trim(), isDir };
      }
      const obj = item as Record<string, unknown>;
      return {
        name: (obj.name as string) || (obj.path as string) || "",
        isDir: !!(obj.isDir || obj.is_dir || obj.isDirectory),
      };
    });
  }

  return resultText
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const isDir =
        line.endsWith("/") ||
        line.toLowerCase().includes("(directory)") ||
        line.toLowerCase().includes("(dir)");
      const name = line.replace(/\(directory\)/gi, "").replace(/\(dir\)/gi, "").trim();
      return { name, isDir };
    });
}

export interface ReadFileDetails {
  filePath: string;
  content: string;
  otherArgs: Record<string, unknown>;
}

export function getReadFileToolDetails(args: string | undefined, result: string | undefined): ReadFileDetails | null {
  const parsedArgs = parseToolArgs(args) || {};
  const filePath = findPath(parsedArgs);
  if (!filePath) return null;

  const otherArgs: Record<string, unknown> = {};
  for (const [key, val] of Object.entries(parsedArgs)) {
    const isPathKey = PATH_KEYS.some((pk) => pk.toLowerCase() === key.toLowerCase());
    if (!isPathKey) otherArgs[key] = val;
  }

  return { filePath, content: result || "", otherArgs };
}

export interface LsTreeNode {
  name: string;
  path: string;
  isDir: boolean;
  children?: LsTreeNode[];
}

// An `ls` result is flat, but entries can still carry slashes (e.g.
// "/memories/agent/", "/memories/user/") that share a common parent the
// listing itself never names. Group those into a real nested tree — same
// technique as file-explorer-editor.tsx's buildFileTree — so shared
// prefixes collapse into one expandable "memories" node instead of two
// separate top-level rows that both start with "/memories/".
export function buildLsTree(items: LsEntry[]): LsTreeNode[] {
  interface MutableNode {
    name: string;
    path: string;
    isDir: boolean;
    children: Map<string, MutableNode>;
  }
  const root = new Map<string, MutableNode>();

  for (const item of items) {
    const parts = item.name.split("/").filter(Boolean);
    if (parts.length === 0) continue;
    let level = root;
    let currentPath = "";
    parts.forEach((part, i) => {
      currentPath = currentPath ? `${currentPath}/${part}` : part;
      const isLast = i === parts.length - 1;
      let node = level.get(part);
      if (!node) {
        node = { name: part, path: currentPath, isDir: isLast ? item.isDir : true, children: new Map() };
        level.set(part, node);
      } else if (isLast) {
        node.isDir = item.isDir;
      }
      level = node.children;
    });
  }

  function finalize(map: Map<string, MutableNode>): LsTreeNode[] {
    return Array.from(map.values())
      .sort((a, b) => {
        if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
        return a.name.localeCompare(b.name);
      })
      .map((n) => ({
        name: n.name,
        path: n.path,
        isDir: n.isDir,
        children: n.children.size ? finalize(n.children) : undefined,
      }));
  }

  return finalize(root);
}

// Common code file extensions, used to pick a "code" vs "text" file icon.
export const CODE_EXTENSIONS = [
  "js",
  "jsx",
  "ts",
  "tsx",
  "json",
  "html",
  "css",
  "py",
  "sh",
  "go",
  "rs",
  "md",
  "yaml",
  "yml",
];

export function fileExtOf(fileName: string): string {
  return fileName.includes(".") ? fileName.split(".").pop()!.toLowerCase() : "";
}
